/// Stable schema for aggregate facade reports and cache identities.
pub const AGGREGATE_EXPLAIN_SCHEMA_VERSION: u32 = 48;

/// Version of the construction-owned direct-route protocol.
pub const AGGREGATE_DIRECT_OWNER_ALGORITHM_VERSION: u32 = 2;

/// Version of the lossless direct terminal-attempt envelope.
pub const AGGREGATE_DIRECT_OWNER_ACCOUNTING_VERSION: u32 = 1;

/// Canonical schema for the facade-authenticated exact-literal count AOT
/// semantic binding.
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_SEMANTIC_BINDING_SCHEMA_VERSION: u32 = 1;

/// Canonical schema for the facade-owned, fixed-policy AOT planning receipt.
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_RECEIPT_SCHEMA_VERSION: u32 = 1;

/// Exact facade construction policy admitted by the v1 AOT compiler.
///
/// This version means `AggregateBuildLimits::aot_count_exact_literal_v1()`,
/// `ForceExactLiteral`, and `ReverseSequentialRows`. The planned-candidate
/// projection verifies every effective value before assigning this tag.
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_POLICY_VERSION: u32 = 1;

/// Fixed source and retained-literal ceilings checked before AOT identity
/// hashing.
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_MAX_SOURCE_BYTES_V1: u64 = 64 << 10;
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_MAX_LITERAL_BYTES_V1: usize = 32;

/// Prospective work ceiling published before any fixed-policy v1 facade
/// effect: quota-bounded syntax work, exact-literal inspection/build, report
/// publication, and both construction-cached AOT identity projections.
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_WORK_UPPER_BOUND_V1: u64 = (1 << 20)
    + 4_096
    + 33
    + 1
    + AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1;

/// Construction-charged ceiling for both canonical SHA-256 projections under
/// the fixed 64-KiB source/policy/ledger envelope.
pub const AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1: u64 = 1 << 20;

/// Whole-match operation fixed before an aggregate plan is constructed.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum AggregateOperation {
    /// Compile a reusable whole-match artifact. Construction is the measured
    /// operation; complete match counting exists only to verify the artifact.
    Compile,
    /// Complete Rust-compatible non-overlapping match spans.
    Spans,
    /// Number of complete non-overlapping matches.
    Count,
    /// Checked sum of every complete match's byte length (`count-spans`).
    SpanSum,
}

/// Why an authenticated whole-match byte-domain proof can complete without
/// source access. All reasons except
/// [`Self::NonemptyAlternativesBelowMinimumBytes`] produce no matches; that
/// reason proves the exact byte-boundary empty-match stream.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum AggregateImpossibleMatchReason {
    /// The canonical HIR denotes the empty language.
    EmptyLanguage,
    /// Every match consumes more bytes than the complete haystack contains.
    BelowMinimumBytes,
    /// Every nonempty top-level alternative consumes more bytes than the
    /// complete haystack contains, leaving an unconditional empty alternative
    /// as the only possible leftmost-first match.
    NonemptyAlternativesBelowMinimumBytes,
    /// Absolute text-start/text-end assertions require the match to consume the
    /// complete haystack, which is longer than every string in the language.
    AboveAbsoluteMaximumBytes,
}

/// Constant-time byte-domain proof retained from canonical HIR properties.
///
/// `regex-syntax` computes minimum and maximum lengths in bytes, including
/// the 1--4 byte width of Unicode scalar classes. Only exact `Start` and `End`
/// look assertions establish `absolute_whole_input`; line-oriented LF/CRLF
/// assertions never do.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
struct AggregateMatchDomainProof {
    minimum_match_bytes: Option<usize>,
    maximum_match_bytes: Option<usize>,
    /// Minimum byte width across every nonempty top-level alternative when
    /// captures erase to one alternation containing an unconditional `Empty`
    /// arm. This proof is deliberately byte-mode only: every byte boundary is
    /// then an eligible empty-match boundary without source inspection.
    ///
    /// Bit zero records the pre-existing absolute-whole-input proof and the
    /// remaining bits store this positive minimum. Keeping both facts in one
    /// word preserves the construction owner's allocation size class.
    domain_flags: usize,
}

const EMPTY_ALTERNATIVE_BRANCH_CHECKS: u8 = 2;
const ABSOLUTE_WHOLE_INPUT_FLAG: usize = 1;

impl AggregateMatchDomainProof {
    fn from_hir(hir: &Hir, unicode: bool) -> Self {
        let properties = hir.properties();
        // In regex-syntax 1.12.4, an alternation that contains an
        // empty-language arm can itself report no cached minimum even when a
        // different arm is viable. Therefore `None` alone cannot authenticate
        // the whole empty language. A directly observed empty root class is
        // sufficient; every uncertain compound shape conservatively retains a
        // zero minimum and reaches ordinary execution.
        let minimum_match_bytes = match properties.minimum_len() {
            Some(minimum) => Some(minimum),
            None if matches!(hir.kind(), HirKind::Class(class) if class.is_empty()) => None,
            None => Some(0),
        };
        let absolute_whole_input = properties.look_set_prefix().contains(Look::Start)
            && properties.look_set_suffix().contains(Look::End);
        let empty_alternative_minimum = if unicode {
            None
        } else {
            empty_alternative_nonempty_minimum_bytes(hir)
        };
        let encoded_empty_alternative_minimum = empty_alternative_minimum
            .and_then(|minimum| minimum.checked_mul(2))
            .unwrap_or(0);
        Self {
            minimum_match_bytes,
            maximum_match_bytes: properties.maximum_len(),
            domain_flags: encoded_empty_alternative_minimum | usize::from(absolute_whole_input),
        }
    }

    const fn absolute_whole_input(&self) -> bool {
        self.domain_flags & ABSOLUTE_WHOLE_INPUT_FLAG != 0
    }

    const fn empty_alternative_nonempty_minimum_bytes(&self) -> Option<usize> {
        let minimum = self.domain_flags >> 1;
        if minimum == 0 { None } else { Some(minimum) }
    }

    #[inline]
    fn impossible(&self, input_bytes: usize) -> Option<(AggregateImpossibleMatchReason, u8)> {
        let Some(minimum) = self.minimum_match_bytes else {
            return Some((AggregateImpossibleMatchReason::EmptyLanguage, 1));
        };
        if input_bytes < minimum {
            return Some((AggregateImpossibleMatchReason::BelowMinimumBytes, 1));
        }
        if self.absolute_whole_input()
            && self
                .maximum_match_bytes
                .is_some_and(|maximum| input_bytes > maximum)
        {
            return Some((AggregateImpossibleMatchReason::AboveAbsoluteMaximumBytes, 2));
        }
        None
    }

    #[inline]
    fn empty_alternative_only(&self, input_bytes: usize) -> Option<usize> {
        let minimum = self.empty_alternative_nonempty_minimum_bytes()?;
        (input_bytes < minimum).then_some(minimum)
    }
}

/// Prove that transparent root captures enclose one ordered top-level
/// alternation with at least one unconditional empty arm and no other nullable
/// arm. Empty-language arms are irrelevant; every remaining arm contributes
/// its canonical minimum byte width.
///
/// Construction accounting owns this bounded inspection through the
/// authenticated syntax/HIR admission: it visits only an already-admitted
/// transparent root chain and its top-level arms, reads cached constant-time
/// properties, performs no recursion, and allocates nothing.
fn empty_alternative_nonempty_minimum_bytes(mut hir: &Hir) -> Option<usize> {
    while let HirKind::Capture(capture) = hir.kind() {
        hir = capture.sub.as_ref();
    }
    let HirKind::Alternation(alternatives) = hir.kind() else {
        return None;
    };
    let mut saw_unconditional_empty = false;
    let mut nonempty_minimum = None;
    for alternative in alternatives {
        let mut branch = alternative;
        while let HirKind::Capture(capture) = branch.kind() {
            branch = capture.sub.as_ref();
        }
        if matches!(branch.kind(), HirKind::Empty) {
            saw_unconditional_empty = true;
            continue;
        }
        let Some(minimum) = alternative.properties().minimum_len() else {
            // A canonical empty-language arm can never alter ordered matching.
            continue;
        };
        if minimum == 0 {
            // A nullable assertion, repetition or compound arm is not an
            // unconditional empty alternative and can affect priority.
            return None;
        }
        nonempty_minimum =
            Some(nonempty_minimum.map_or(minimum, |current: usize| current.min(minimum)));
    }
    if saw_unconditional_empty {
        nonempty_minimum
    } else {
        None
    }
}

/// Source-free operation receipt for a terminal whole-match byte domain.
/// Terminal success reports retain either an exact no-match proof or an exact
/// byte-boundary empty-match proof before any source access.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct AggregateMatchDomainExecutionReceipt {
    proof: AggregateMatchDomainProof,
    operation: AggregateOperation,
    input_bytes: usize,
    reason: AggregateImpossibleMatchReason,
    branch_checks: u8,
    value: u64,
    empty_match_count: usize,
}

impl AggregateMatchDomainExecutionReceipt {
    #[must_use]
    pub const fn operation(&self) -> AggregateOperation {
        self.operation
    }

    #[must_use]
    pub const fn input_bytes(&self) -> usize {
        self.input_bytes
    }

    #[must_use]
    pub const fn minimum_match_bytes(&self) -> Option<usize> {
        self.proof.minimum_match_bytes
    }

    #[must_use]
    pub const fn maximum_match_bytes(&self) -> Option<usize> {
        self.proof.maximum_match_bytes
    }

    /// Minimum width of every nonempty top-level alternative when an
    /// unconditional empty arm is the only possible match.
    #[must_use]
    pub const fn empty_alternative_nonempty_minimum_bytes(&self) -> Option<usize> {
        self.proof.empty_alternative_nonempty_minimum_bytes()
    }

    #[must_use]
    pub const fn absolute_whole_input(&self) -> bool {
        self.proof.absolute_whole_input()
    }

    #[must_use]
    pub const fn reason(&self) -> AggregateImpossibleMatchReason {
        self.reason
    }

    /// Fixed proof predicates charged before the terminal result. The
    /// compiler-bounded preflight charges at most two; this is logical
    /// accounting rather than a claim about emitted CPU branches.
    #[must_use]
    pub const fn branch_checks(&self) -> u8 {
        self.branch_checks
    }

    /// The proof never reads a source byte.
    #[must_use]
    pub const fn source_bytes_read(&self) -> usize {
        0
    }

    /// The proof and receipt are inline and operation execution allocates
    /// nothing.
    #[must_use]
    pub const fn operation_allocations(&self) -> usize {
        0
    }

    /// Exact operation value established by the source-free proof.
    #[must_use]
    pub const fn value(&self) -> u64 {
        self.value
    }

    /// Exact number of empty matches selected at byte boundaries. This is zero
    /// for the pre-existing no-match domain reasons.
    #[must_use]
    pub const fn empty_match_count(&self) -> usize {
        self.empty_match_count
    }

    /// Exact constant operation work charged by the source-free proof.
    #[must_use]
    pub fn operation_work(&self) -> usize {
        usize::from(self.branch_checks)
    }

    fn new(
        proof: &AggregateMatchDomainProof,
        operation: AggregateOperation,
        input_bytes: usize,
        limits: &AggregateRunLimits,
    ) -> Option<Self> {
        if !matches!(
            operation,
            AggregateOperation::Count | AggregateOperation::SpanSum
        ) {
            return None;
        }
        if let Some((reason, branch_checks)) = proof.impossible(input_bytes) {
            return Some(Self {
                proof: *proof,
                operation,
                input_bytes,
                reason,
                branch_checks,
                value: 0,
                empty_match_count: 0,
            });
        }
        proof.empty_alternative_only(input_bytes)?;
        let empty_match_count = input_bytes.checked_add(1)?;
        let continuation = limits.continuation;
        if empty_match_count > continuation.max_boundaries
            || empty_match_count > continuation.max_match_events
            || empty_match_count > continuation.max_output_matches
            || usize::from(EMPTY_ALTERNATIVE_BRANCH_CHECKS) > continuation.max_work
        {
            return None;
        }
        let value = match operation {
            AggregateOperation::Count => u64::try_from(empty_match_count).ok()?,
            AggregateOperation::SpanSum => 0,
            AggregateOperation::Compile | AggregateOperation::Spans => return None,
        };
        Some(Self {
            proof: *proof,
            operation,
            input_bytes,
            reason: AggregateImpossibleMatchReason::NonemptyAlternativesBelowMinimumBytes,
            branch_checks: EMPTY_ALTERNATIVE_BRANCH_CHECKS,
            value,
            empty_match_count,
        })
    }

    fn authenticates(
        &self,
        proof: &AggregateMatchDomainProof,
        operation: AggregateOperation,
        limits: &AggregateRunLimits,
    ) -> bool {
        self.proof == *proof
            && self.operation == operation
            && Self::new(proof, operation, self.input_bytes, limits).as_ref() == Some(self)
    }
}

/// Exact source-free full-window envelope published by an authenticated
/// retained direct owner.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AggregateRetainedFullWindowUpperBounds {
    /// Established or dispatched Unicode scalar reducer.
    UnicodeScalar(UnicodeScalarAggregateUpperBounds),
    /// Established or dispatched two-branch prefix/class count/span-sum reducer.
    PrefixClassAlternation(PrefixClassAlternationUpperBounds),
    /// Literal/class-run/literal count or span-sum reducer.
    LiteralClassRunLiteral(LiteralClassRunLiteralUpperBounds),
    /// Required-inner-literal Unicode maximal-run reducer.
    ReverseInner(ReverseInnerUpperBounds),
    /// Bounded-context count reducer.
    BoundedContextCount(BoundedContextUpperBounds),
    /// Bounded-context span-sum reducer.
    BoundedContextSpanSum(BoundedContextSpanSumUpperBounds),
}

/// Construction-time aggregate plan policy.
#[derive(Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum AggregatePlanSelection {
    /// Select an exact-literal, direct-Unicode, or finite-language plan when
    /// canonical HIR proves eligibility; otherwise construct continuation.
    #[default]
    Auto,
    /// Require the direct canonical exact-literal proof.
    ForceExactLiteral,
    /// Skip exact-literal inspection and require the continuation program.
    ForceContinuation,
}

/// Operation plan family chosen at construction time.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum AggregatePlanKind {
    /// SIMD-aware `memmem::Finder::find_iter` whole-operation reducer.
    ExactLiteral,
    /// Direct Unicode scalar class/run stream over compact canonical ranges.
    /// This is not the continuation state engine.
    UnicodeScalarClass,
    /// Single-pass maximal run reducer for canonical `\b\w{m,}\b`, bare
    /// greedy nonempty unbounded root word repetitions, or a Unicode-off exact
    /// repetition of one canonical byte class.
    WordRun,
    /// One monotone literal-candidate stream for the exact ordered
    /// `(?m:^L)|(?m:L$)` shape.
    LiteralAssertions,
    /// One monotone consecutive-delimiter stream for
    /// `D [^D]{0,N} T D` under Unicode-off byte semantics.
    BlockingDelimiter,
    /// One monotone maximal-token stream for the Unicode-off ASCII grammar
    /// `\w+\s+L\s+\w+`, optionally surrounded by ASCII word boundaries.
    TokenPhrase,
    /// Direct bounded circular-window reducer for
    /// `PREFIX MIDDLE{N} SUFFIX` class/literal sequences after transparent
    /// whole-match capture erasure.
    FixedClassSandwich,
    /// Direct ordered scalar-property grammar with constant phase state.
    GraphemeScalarDfa,
    /// Linear count reducer for a greedy bounded sequence of deterministic
    /// `HEAD BODY+ TRAIL*` byte-class units.
    BoundedClassSequence,
    /// Constant-frontier count reducer for a fixed number of identical,
    /// one-byte-separator-delimited bounded byte-class fields.
    BoundedSeparatedFields,
    /// Two ordered literal-prefix/greedy-byte-class alternatives merged from
    /// persistent monotone occurrence streams.
    PrefixClassAlternation,
    /// Fixed literals bracketing one maximal nonempty Unicode-off byte-class
    /// run, reduced by one monotone run stream.
    LiteralClassRunLiteral,
    /// Required ASCII literals inside the strict interior of one maximal
    /// Unicode scalar-class run.
    ReverseInner,
    /// Two swapped literal endpoints separated by one common finite greedy
    /// byte-class gap and reduced by bounded start/endpoint arbitration.
    BoundedLiteralPair,
    /// Linear literal-interval stream for a fixed-class/bounded-gap context.
    BoundedContext,
    /// Fixed candidate derived from absolute StartText/EndText over the
    /// original haystack, with an eager residual only for scalar envelopes.
    FixedAbsoluteDomain,
    /// Ordered finite HIR lowered to one reversed shared dense or sparse
    /// automaton and a bounded initial/progressed reducer ring.
    FiniteLiteralDfa,
    /// Small ordered finite HIR lowered to one bounded packed literal scanner
    /// before the dense finite-language route is considered.
    PackedFiniteLiteral,
    /// Finite nonempty ASCII-word bodies guarded on both endpoints, lowered
    /// to an eager exact dictionary and allocation-free maximal-word scan.
    GuardedAsciiWordDictionary,
    /// Finite ASCII-word alternatives with full Unicode word boundaries,
    /// lowered to one maximal ASCII-word-run literal-set reducer.
    GuardedUnicodeWordLiteralSet,
    /// One fixed-width sequence of byte predicates lowered to an inline
    /// 64-bit Shift-And state and byte-to-position masks.
    FixedPredicateWord64,
    /// Bounded prioritized continuation program from `fre-aggregate`.
    ContinuationProgram,
}

/// Stable identity for the selected operation-specific implementation.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[allow(
    clippy::large_enum_variant,
    reason = "the packed route retains its complete Copy native classifier identity inline so construction and execution authentication add no allocation"
)]
pub enum AggregatePlanIdentity {
    /// Exact-literal plan plus count/span-sum operation identity.
    ExactLiteral(AggregateExactLiteralIdentity),
    /// Root Unicode scalar-class proof plus native reducer identity.
    UnicodeScalar(AggregateUnicodeScalarIdentity),
    /// Complete word-run or fixed byte-class chunk proof and operation
    /// identity.
    WordRun(AggregateWordRunIdentity),
    /// Ordered line-assertion/literal proof and native operation identity.
    LiteralAssertions(AggregateLiteralAssertionsIdentity),
    /// Blocking-delimiter grammar proof and native operation identity.
    BlockingDelimiter(AggregateBlockingDelimiterIdentity),
    /// ASCII token-phrase grammar proof and native operation identity.
    TokenPhrase(AggregateTokenPhraseIdentity),
    /// Fixed-width three-atom class sequence plus native reducer identity.
    FixedClassSandwich(AggregateFixedClassSandwichIdentity),
    /// Ordered scalar-property grammar plus native reducer identity.
    GraphemeScalarDfa(AggregateGraphemeScalarDfaIdentity),
    /// Unicode-off compound byte-class sequence plus count identity.
    BoundedClassSequence(BoundedClassSequenceOperationIdentity),
    /// Unicode-off bounded separated-field proof plus count identity.
    BoundedSeparatedFields(AggregateBoundedSeparatedFieldsIdentity),
    /// Unicode-off two-branch prefix/class proof and native reduction identity.
    PrefixClassAlternation(AggregatePrefixClassAlternationIdentity),
    /// Unicode-off literal/class-run/literal proof and operation identity.
    LiteralClassRunLiteral(AggregateLiteralClassRunLiteralIdentity),
    /// Unicode scalar-class reverse-inner proof and operation identity.
    ReverseInner(AggregateReverseInnerIdentity),
    /// Unicode-off swapped bounded literal-pair proof and native operation
    /// identity.
    BoundedLiteralPair(AggregateBoundedLiteralPairIdentity),
    /// Bounded byte-context proof plus native count identity.
    BoundedContext(AggregateBoundedContextIdentity),
    /// Closed fixed absolute-domain descriptor and declared residual identity.
    FixedAbsoluteDomain(AggregateFixedAbsoluteDomainIdentity),
    /// Finite-language DFA identity; the syntax key retains exact source and
    /// profile identity, including order, duplicates and arbitrary bytes.
    FiniteLiteral(AggregateFiniteLiteralIdentity),
    /// Guarded ASCII-word dictionary and operation identity. The syntax key
    /// retains exact HIR order, captures, duplicates, and profile inputs.
    GuardedAsciiWord(AggregateGuardedAsciiWordIdentity),
    /// Guarded Unicode-word maximal-run identity.
    GuardedUnicodeWord(AggregateGuardedUnicodeWordIdentity),
    /// Fixed byte-predicate Shift-And operation identity.
    FixedPredicateWord64(FixedPredicateWord64OperationIdentity),
    /// Semantic continuation-program identity.
    Continuation(AggregateContinuationIdentity),
}

