fn packed_finite_terminal_effect(
    actual: PackedOrderedLiteralAggregateBuildAttemptActual,
    boundary_work: usize,
    prior: AggregateConstructionEffect,
) -> Option<AggregateConstructionEffect> {
    let mut effect = include_construction_work(packed_finite_build_effect(actual), boundary_work)?;
    effect.released_persistent_bytes = prior.retained_persistent_bytes;
    Some(effect)
}

fn fixed_predicate_build_effect(
    actual: FixedPredicateWord64BuildAttemptActual,
    inspection: AggregateConstructionEffect,
) -> Option<AggregateConstructionEffect> {
    Some(AggregateConstructionEffect {
        work: inspection.work.checked_add(actual.work)?,
        allocations: inspection.allocations.checked_add(actual.allocations)?,
        allocated_bytes: inspection.allocated_bytes,
        copied_bytes: inspection.copied_bytes.checked_add(actual.copied_bytes)?,
        initialized_bytes: inspection
            .initialized_bytes
            .checked_add(actual.initialized_bytes)?,
        retained_persistent_bytes: actual.live_persistent_bytes,
        released_persistent_bytes: 0,
        co_live_bytes: inspection.co_live_bytes.max(actual.peak_bytes),
    })
}

fn fixed_predicate_abandonment(
    prior: Option<(AggregateConstructionEffect, usize)>,
    effect: AggregateConstructionEffect,
    build: FixedPredicateWord64BuildAttemptActual,
) -> Option<AggregateConstructionAbandonment> {
    let (prior, prior_abandonable_bytes) =
        prior.unwrap_or((AggregateConstructionEffect::default(), 0));
    Some(AggregateConstructionAbandonment {
        work: prior.work.checked_add(effect.work)?,
        allocations: prior.allocations.checked_add(effect.allocations)?,
        bytes: prior_abandonable_bytes
            .checked_add(effect.allocated_bytes)?
            .checked_add(build.initialized_bytes)?,
        released_persistent_bytes: prior
            .retained_persistent_bytes
            .checked_add(effect.retained_persistent_bytes)?,
    })
}

fn continuation_compile_effect(
    actual: fre_aggregate::CompileConstructionActual,
) -> AggregateConstructionEffect {
    AggregateConstructionEffect {
        work: u64::try_from(actual.work).unwrap_or(u64::MAX),
        allocations: actual.allocations,
        allocated_bytes: actual.allocated_bytes,
        copied_bytes: actual.copied_bytes,
        initialized_bytes: actual.initialized_bytes,
        retained_persistent_bytes: actual.live_construction_bytes,
        released_persistent_bytes: 0,
        co_live_bytes: actual.construction_peak_bytes,
    }
}

/// Project a stage-local effect through an unpublished hard terminal.
///
/// The lower receipt observes construction bytes immediately before its
/// failure unwinds. Those bytes still contribute to cumulative counters and
/// the co-live peak, but no stage artifact escapes in the aggregate error, so
/// none remain live after the aggregate terminal is closed.
const fn hard_terminal_effect(effect: AggregateConstructionEffect) -> AggregateConstructionEffect {
    AggregateConstructionEffect {
        retained_persistent_bytes: 0,
        ..effect
    }
}

fn construction_stage_for_report(report: &AggregateBuildReport) -> AggregateConstructionStage {
    match report.plan {
        AggregatePlanKind::ExactLiteral => AggregateConstructionStage::ExactLiteral,
        AggregatePlanKind::UnicodeScalarClass => AggregateConstructionStage::UnicodeScalar,
        AggregatePlanKind::WordRun => AggregateConstructionStage::WordRun,
        AggregatePlanKind::LiteralAssertions => AggregateConstructionStage::LiteralAssertions,
        AggregatePlanKind::BlockingDelimiter => AggregateConstructionStage::BlockingDelimiter,
        AggregatePlanKind::TokenPhrase => AggregateConstructionStage::TokenPhrase,
        AggregatePlanKind::FixedClassSandwich => AggregateConstructionStage::FixedClassSandwich,
        AggregatePlanKind::GraphemeScalarDfa => AggregateConstructionStage::GraphemeScalarDfa,
        AggregatePlanKind::BoundedClassSequence => AggregateConstructionStage::BoundedClassSequence,
        AggregatePlanKind::BoundedSeparatedFields => {
            AggregateConstructionStage::BoundedSeparatedFields
        }
        AggregatePlanKind::PrefixClassAlternation => {
            AggregateConstructionStage::PrefixClassAlternation
        }
        AggregatePlanKind::BoundedLiteralPair => AggregateConstructionStage::BoundedLiteralPair,
        AggregatePlanKind::LiteralClassRunLiteral => {
            AggregateConstructionStage::LiteralClassRunLiteral
        }
        AggregatePlanKind::ReverseInner => AggregateConstructionStage::LiteralClassRunLiteral,
        AggregatePlanKind::BoundedContext
            if matches!(
                report.plan_identity,
                AggregatePlanIdentity::BoundedContext(identity)
                    if identity.kernel.plan_id == BOUNDED_AFFIX_PLAN_ID
            ) =>
        {
            AggregateConstructionStage::BoundedAffix
        }
        AggregatePlanKind::BoundedContext => AggregateConstructionStage::BoundedContext,
        AggregatePlanKind::FixedAbsoluteDomain => AggregateConstructionStage::FixedAbsolute,
        AggregatePlanKind::FiniteLiteralDfa
            if matches!(
                report.build,
                AggregateBuildAccounting::SparseFiniteLiteral(_)
            ) =>
        {
            AggregateConstructionStage::SparseFiniteRoot
        }
        AggregatePlanKind::FiniteLiteralDfa => AggregateConstructionStage::DenseFinite,
        AggregatePlanKind::PackedFiniteLiteral
            if matches!(
                report.plan_identity,
                AggregatePlanIdentity::FiniteLiteral(AggregateFiniteLiteralIdentity {
                    semantics: AggregateFiniteLiteralSemantics::UnicodeOffGreedyBoundedDotPrefix,
                    ..
                })
            ) =>
        {
            AggregateConstructionStage::PrefixClassAlternation
        }
        AggregatePlanKind::PackedFiniteLiteral => AggregateConstructionStage::PackedFinite,
        AggregatePlanKind::GuardedAsciiWordDictionary
        | AggregatePlanKind::GuardedUnicodeWordLiteralSet => {
            AggregateConstructionStage::GeneralFiniteExtraction
        }
        AggregatePlanKind::FixedPredicateWord64 => AggregateConstructionStage::FixedPredicateWord64,
        AggregatePlanKind::ContinuationProgram => AggregateConstructionStage::Continuation,
    }
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the complete Copy plan identity is matched by value throughout the construction closure protocol"
)]
fn construction_stage_closes_plan(
    stage: AggregateConstructionStage,
    plan: AggregatePlanKind,
    identity: AggregatePlanIdentity,
) -> bool {
    match (stage, plan, identity) {
        (
            AggregateConstructionStage::PackedFinite,
            AggregatePlanKind::PackedFiniteLiteral,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) => return packed_finite_identity_closes_native(&identity),
        (
            AggregateConstructionStage::PrefixClassAlternation,
            AggregatePlanKind::PackedFiniteLiteral,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) if identity.semantics
            == AggregateFiniteLiteralSemantics::UnicodeOffGreedyBoundedDotPrefix =>
        {
            return packed_finite_identity_closes_native(&identity);
        }
        (
            AggregateConstructionStage::DenseFinite,
            AggregatePlanKind::FiniteLiteralDfa,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) => {
            return identity.algorithm == ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && identity.packed_operation_identity.is_none();
        }
        (
            AggregateConstructionStage::SparseFiniteRoot,
            AggregatePlanKind::FiniteLiteralDfa,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) => {
            return identity.algorithm == SPARSE_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && identity.packed_operation_identity.is_none();
        }
        _ => {}
    }
    matches!(
        (stage, plan, identity),
        (
            AggregateConstructionStage::ExactLiteral,
            AggregatePlanKind::ExactLiteral,
            AggregatePlanIdentity::ExactLiteral(_),
        ) | (
            AggregateConstructionStage::UnicodeScalar,
            AggregatePlanKind::UnicodeScalarClass,
            AggregatePlanIdentity::UnicodeScalar(_),
        ) | (
            AggregateConstructionStage::WordRun,
            AggregatePlanKind::WordRun,
            AggregatePlanIdentity::WordRun(_),
        ) | (
            AggregateConstructionStage::LiteralAssertions,
            AggregatePlanKind::LiteralAssertions,
            AggregatePlanIdentity::LiteralAssertions(_),
        ) | (
            AggregateConstructionStage::BlockingDelimiter,
            AggregatePlanKind::BlockingDelimiter,
            AggregatePlanIdentity::BlockingDelimiter(_),
        ) | (
            AggregateConstructionStage::TokenPhrase,
            AggregatePlanKind::TokenPhrase,
            AggregatePlanIdentity::TokenPhrase(_),
        ) | (
            AggregateConstructionStage::FixedClassSandwich,
            AggregatePlanKind::FixedClassSandwich,
            AggregatePlanIdentity::FixedClassSandwich(_),
        ) | (
            AggregateConstructionStage::GraphemeScalarDfa,
            AggregatePlanKind::GraphemeScalarDfa,
            AggregatePlanIdentity::GraphemeScalarDfa(_),
        ) | (
            AggregateConstructionStage::BoundedClassSequence,
            AggregatePlanKind::BoundedClassSequence,
            AggregatePlanIdentity::BoundedClassSequence(_),
        ) | (
            AggregateConstructionStage::BoundedSeparatedFields,
            AggregatePlanKind::BoundedSeparatedFields,
            AggregatePlanIdentity::BoundedSeparatedFields(_),
        ) | (
            AggregateConstructionStage::PrefixClassAlternation,
            AggregatePlanKind::PrefixClassAlternation,
            AggregatePlanIdentity::PrefixClassAlternation(_),
        ) | (
            AggregateConstructionStage::BoundedLiteralPair,
            AggregatePlanKind::BoundedLiteralPair,
            AggregatePlanIdentity::BoundedLiteralPair(_),
        ) | (
            AggregateConstructionStage::LiteralClassRunLiteral,
            AggregatePlanKind::LiteralClassRunLiteral,
            AggregatePlanIdentity::LiteralClassRunLiteral(_),
        ) | (
            AggregateConstructionStage::LiteralClassRunLiteral,
            AggregatePlanKind::ReverseInner,
            AggregatePlanIdentity::ReverseInner(_),
        ) | (
            AggregateConstructionStage::BoundedAffix | AggregateConstructionStage::BoundedContext,
            AggregatePlanKind::BoundedContext,
            AggregatePlanIdentity::BoundedContext(_),
        ) | (
            AggregateConstructionStage::FixedAbsolute,
            AggregatePlanKind::FixedAbsoluteDomain,
            AggregatePlanIdentity::FixedAbsoluteDomain(_),
        ) | (
            AggregateConstructionStage::GeneralFiniteExtraction,
            AggregatePlanKind::GuardedAsciiWordDictionary,
            AggregatePlanIdentity::GuardedAsciiWord(_),
        ) | (
            AggregateConstructionStage::GeneralFiniteExtraction,
            AggregatePlanKind::GuardedUnicodeWordLiteralSet,
            AggregatePlanIdentity::GuardedUnicodeWord(_),
        ) | (
            AggregateConstructionStage::FixedPredicateWord64,
            AggregatePlanKind::FixedPredicateWord64,
            AggregatePlanIdentity::FixedPredicateWord64(_),
        ) | (
            AggregateConstructionStage::Continuation,
            AggregatePlanKind::ContinuationProgram,
            AggregatePlanIdentity::Continuation(_),
        )
    )
}

#[allow(
    clippy::large_types_passed_by_value,
    reason = "the complete Copy plan identity is matched by value throughout the construction closure protocol"
)]
fn construction_strategy_closes_plan(
    requested: AggregateStrategy,
    continuation: Option<AggregateStrategy>,
    plan: AggregatePlanKind,
    identity: AggregatePlanIdentity,
) -> bool {
    match (plan, identity) {
        (
            AggregatePlanKind::FixedAbsoluteDomain,
            AggregatePlanIdentity::FixedAbsoluteDomain(identity),
        ) => {
            let scalar = identity.kernel.descriptor.kind()
                == FixedAbsoluteDomainDescriptorKind::WholeScalarEnvelope;
            if scalar {
                continuation == Some(requested) && identity.residual_strategy == Some(requested)
            } else {
                continuation.is_none() && identity.residual_strategy.is_none()
            }
        }
        (AggregatePlanKind::ContinuationProgram, AggregatePlanIdentity::Continuation(_)) => {
            continuation == Some(requested)
        }
        _ => continuation.is_none(),
    }
}

fn complete_construction_selector_ledger(
    transaction: &mut AggregateConstructionTransaction,
    report: &AggregateBuildReport,
) -> Result<AggregateConstructionStage, crate::AggregateConstructionStateError> {
    let selected = construction_stage_for_report(report);
    if transaction.selected_stage() == Some(selected) {
        Ok(selected)
    } else {
        Err(crate::AggregateConstructionStateError::InvalidTransition)
    }
}

fn finish_construction_failure(
    context: AggregateConstructionContext,
    source: AggregateBuildError,
    sealed_stage: AggregateConstructionStage,
) -> AggregateConstructionAttemptError {
    let receipt = match context.transaction.finish_failure() {
        Ok(receipt) => receipt,
        Err(_state) => {
            unreachable!("construction transaction failed to close its hard terminal")
        }
    };
    let Some(source_owner) = context.source_owner else {
        unreachable!("construction terminal lost its exact source owner");
    };
    AggregateConstructionAttemptError::new(
        source,
        receipt,
        source_owner,
        context.syntax_attempt,
        sealed_stage,
    )
}

/// Private closure evidence excluded from structural public report/cache
/// equality. Independent constructions of the same request remain equal as
/// before U0-F, while explicit closure methods still authenticate the exact
/// source-bound receipts retained here.
#[derive(Clone, Debug)]
struct AggregateClosureEvidence<T>(Option<T>);

impl<T> AggregateClosureEvidence<T> {
    const fn empty() -> Self {
        Self(None)
    }

    const fn from_option(value: Option<T>) -> Self {
        Self(value)
    }

    const fn as_ref(&self) -> Option<&T> {
        self.0.as_ref()
    }

    fn set(&mut self, value: Option<T>) {
        self.0 = value;
    }
}

impl<T> PartialEq for AggregateClosureEvidence<T> {
    fn eq(&self, _other: &Self) -> bool {
        true
    }
}

impl<T> Eq for AggregateClosureEvidence<T> {}

/// Construction-unique closure retained with the public receipt.
///
/// The receipt remains the stable public projection. The private Arc binds
/// that projection to the exact report/cache owner that was published, so a
/// structurally equal receipt or source key from another construction cannot
/// authenticate this artifact.
#[derive(Clone, Debug)]
struct AggregateClosedConstructionEvidence {
    receipt: AggregateConstructionReceipt,
    report_seal: Arc<AggregatePublishedReportSeal>,
}

/// Auditable construction facts for one operation-specific aggregate plan.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateBuildReport {
    /// Report schema.
    pub schema_version: u32,
    /// Closed whole-construction receipt. This is populated by the outer
    /// transaction before any compiled artifact becomes observable.
    construction_attempt: AggregateClosureEvidence<AggregateClosedConstructionEvidence>,
    /// Independent artifact-side handle to the construction-unique report
    /// seal. Closure requires pointer equality with the receipt-side handle.
    published_artifact_owner: AggregateClosureEvidence<Arc<AggregatePublishedReportSeal>>,
    /// Nested syntax-attempt receipt whose exact source owner is the
    /// colocated `syntax_key`.
    syntax_attempt: AggregateClosureEvidence<fre_syntax::ParseAttemptReceipt>,
    /// Full syntax/cache input, including original pattern and profile. The
    /// shared allocation is created during construction, never reducer timing.
    pub syntax_key: Arc<CacheKey>,
    /// What syntax parsing established about constructor admission.
    pub admission: AdmissionStatus,
    /// Exact syntax counters before capture erasure.
    pub syntax: ParseSummary,
    /// Operation selected before compilation.
    pub operation: AggregateOperation,
    /// Requested construction-time plan policy.
    pub selection: AggregatePlanSelection,
    /// Original caller-selected continuation strategy, including when a
    /// direct plan makes `continuation_strategy` inapplicable.
    pub requested_strategy: AggregateStrategy,
    /// Complete caller-supplied construction limits authenticated by the
    /// whole-construction receipt.
    pub build_limits: AggregateBuildLimits,
    /// Plan family selected before publication.
    pub plan: AggregatePlanKind,
    /// Continuation storage strategy, present for continuation plans and the
    /// scalar fixed-domain composite's eager residual; absent for direct-only
    /// plans.
    pub continuation_strategy: Option<AggregateStrategy>,
    /// The only capture treatment admitted by these whole-match APIs.
    pub capture_semantics: AggregateCaptureSemantics,
    /// Direct-root exact-literal inspection work. This is zero when forced
    /// continuation skips inspection.
    pub planner_work: usize,
    /// Root Unicode scalar-class structural inspection work. This is zero when
    /// scalar inspection is skipped; otherwise it records the attempted HIR
    /// and canonical-range inspection even when continuation is selected. It
    /// is not an executed-CPU-instruction count.
    pub unicode_scalar_planner_work: usize,
    /// Direct word-run HIR/range/shape inspection work. This
    /// remains nonzero when an ineligible inspection precedes another
    /// selected family.
    pub word_run_planner_work: usize,
    /// Ordered line-assertion literal HIR/literal inspection work. This
    /// remains nonzero when an ineligible inspection precedes another family.
    pub literal_assertions_planner_work: usize,
    /// Blocking-delimiter HIR/class/complement inspection work. This remains
    /// nonzero when an ineligible inspection precedes another family.
    pub blocking_delimiter_planner_work: usize,
    /// ASCII token-phrase HIR/class/literal inspection work. This remains
    /// nonzero when an ineligible inspection precedes another family.
    pub token_phrase_planner_work: usize,
    /// Fixed-class structural inspection work, including every HIR node and
    /// canonical range examined through transparent captures.
    pub fixed_class_sandwich_planner_work: usize,
    /// Charged direct bounded-affix inspection work, including an ineligible
    /// inspection followed by another plan.
    pub bounded_affix_planner_work: usize,
    /// Ordered scalar-grammar HIR/range inspection work.
    pub grapheme_scalar_dfa_planner_work: usize,
    /// Bounded compound-class structural inspection work, including every
    /// HIR/range visit and admitted disjointness-comparison upper bound.
    pub bounded_class_sequence_planner_work: usize,
    /// Bounded separated-field structural inspection work, including every
    /// HIR/range visit and repeated/final field equality-comparison bound.
    pub bounded_separated_fields_planner_work: usize,
    /// Two-branch prefix/class structural inspection work. Every HIR node,
    /// literal byte, class range and self-overlap comparison is included.
    pub prefix_class_alternation_planner_work: usize,
    /// Literal/class-run/literal structural inspection work, including every
    /// HIR node, literal byte, class range and boundary membership probe.
    pub literal_class_run_literal_planner_work: usize,
    /// Swapped bounded literal-pair structural inspection work. Every visited
    /// HIR node, literal byte, canonical class range and shape comparison is
    /// included, including an ineligible inspection followed by another plan.
    pub bounded_literal_pair_planner_work: usize,
    /// Bounded-context structural inspection work.
    pub bounded_context_planner_work: usize,
    /// Fixed absolute-domain canonical-HIR inspection work.
    pub fixed_absolute_planner_work: u32,
    /// Checked finite-language root inspection and, for the dense route,
    /// analysis/expansion work; zero when finite inspection is skipped.
    /// This remains nonzero when `Auto` proves a finite language but a typed
    /// caller limit rejects the optional dense/sparse automaton preflight and
    /// continuation is selected. A rejected automaton publishes neither build
    /// accounting nor plan identity; its caller-bounded preflight is not
    /// double-counted as work of the selected continuation artifact.
    pub finite_planner_work: u64,
    /// Transparent capture-node visits charged by the selected plan builder.
    /// A scalar fixed-domain composite includes both guard inspection and its
    /// eagerly compiled residual's capture-erasure work.
    pub capture_erasure_work: usize,
    /// Capture annotations removed without changing whole-match semantics.
    pub captures_erased: usize,
    /// Exact construction accounting for the selected plan.
    pub build: AggregateBuildAccounting,
    /// Stable operation-specific selected-plan identity.
    pub plan_identity: AggregatePlanIdentity,
    /// Construction-owned copy that prevents a caller from transplanting a
    /// different bounded separated-field resource certificate into this
    /// report while retaining the original compiled artifact.
    sealed_bounded_separated_fields_identity: Option<AggregateBoundedSeparatedFieldsIdentity>,
    sealed_required_internal_anchor_identity: Option<AggregateRequiredInternalAnchorSeal>,
    sealed_url_aggregate_identity: Option<AggregateUrlOrFixedSeal>,
    /// Selected plan's retained capacity/persistent bytes.
    pub retained_capacity_bytes: usize,
}

/// Immutable success-only snapshot of every public build-report field.
///
/// This is deliberately private and construction-unique. Equality of the
/// public fields is necessary, while pointer equality of the owning Arc is
/// what rejects cross-construction splices between structurally equal plans.
#[derive(Debug)]
struct AggregatePublishedReportSeal {
    schema_version: u32,
    syntax_key: Weak<CacheKey>,
    admission: AdmissionStatus,
    syntax: ParseSummary,
    operation: AggregateOperation,
    selection: AggregatePlanSelection,
    requested_strategy: AggregateStrategy,
    build_limits: AggregateBuildLimits,
    plan: AggregatePlanKind,
    construction_stage: AggregateConstructionStage,
    continuation_strategy: Option<AggregateStrategy>,
    capture_semantics: AggregateCaptureSemantics,
    planner_work: usize,
    unicode_scalar_planner_work: usize,
    word_run_planner_work: usize,
    literal_assertions_planner_work: usize,
    blocking_delimiter_planner_work: usize,
    token_phrase_planner_work: usize,
    fixed_class_sandwich_planner_work: usize,
    bounded_affix_planner_work: usize,
    grapheme_scalar_dfa_planner_work: usize,
    bounded_class_sequence_planner_work: usize,
    bounded_separated_fields_planner_work: usize,
    prefix_class_alternation_planner_work: usize,
    literal_class_run_literal_planner_work: usize,
    bounded_literal_pair_planner_work: usize,
    bounded_context_planner_work: usize,
    fixed_absolute_planner_work: u32,
    finite_planner_work: u64,
    capture_erasure_work: usize,
    captures_erased: usize,
    build: AggregateBuildAccounting,
    plan_identity: AggregatePlanIdentity,
    match_domain: AggregateMatchDomainProof,
    retained_capacity_bytes: usize,
}

impl AggregatePublishedReportSeal {
    fn from_report(report: &AggregateBuildReport, match_domain: AggregateMatchDomainProof) -> Self {
        Self {
            schema_version: report.schema_version,
            syntax_key: Arc::downgrade(&report.syntax_key),
            admission: report.admission,
            syntax: report.syntax.clone(),
            operation: report.operation,
            selection: report.selection,
            requested_strategy: report.requested_strategy,
            build_limits: report.build_limits,
            plan: report.plan,
            construction_stage: construction_stage_for_report(report),
            continuation_strategy: report.continuation_strategy,
            capture_semantics: report.capture_semantics,
            planner_work: report.planner_work,
            unicode_scalar_planner_work: report.unicode_scalar_planner_work,
            word_run_planner_work: report.word_run_planner_work,
            literal_assertions_planner_work: report.literal_assertions_planner_work,
            blocking_delimiter_planner_work: report.blocking_delimiter_planner_work,
            token_phrase_planner_work: report.token_phrase_planner_work,
            fixed_class_sandwich_planner_work: report.fixed_class_sandwich_planner_work,
            bounded_affix_planner_work: report.bounded_affix_planner_work,
            grapheme_scalar_dfa_planner_work: report.grapheme_scalar_dfa_planner_work,
            bounded_class_sequence_planner_work: report.bounded_class_sequence_planner_work,
            bounded_separated_fields_planner_work: report.bounded_separated_fields_planner_work,
            prefix_class_alternation_planner_work: report.prefix_class_alternation_planner_work,
            literal_class_run_literal_planner_work: report.literal_class_run_literal_planner_work,
            bounded_literal_pair_planner_work: report.bounded_literal_pair_planner_work,
            bounded_context_planner_work: report.bounded_context_planner_work,
            fixed_absolute_planner_work: report.fixed_absolute_planner_work,
            finite_planner_work: report.finite_planner_work,
            capture_erasure_work: report.capture_erasure_work,
            captures_erased: report.captures_erased,
            build: report.build,
            plan_identity: report.plan_identity,
            match_domain,
            retained_capacity_bytes: report.retained_capacity_bytes,
        }
    }

    fn matches_report(&self, report: &AggregateBuildReport) -> bool {
        self.syntax_key.as_ptr() == Arc::as_ptr(&report.syntax_key)
            && self.schema_version == report.schema_version
            && self.admission == report.admission
            && self.syntax == report.syntax
            && self.operation == report.operation
            && self.selection == report.selection
            && self.requested_strategy == report.requested_strategy
            && self.build_limits == report.build_limits
            && self.plan == report.plan
            && self.construction_stage == construction_stage_for_report(report)
            && self.continuation_strategy == report.continuation_strategy
            && self.capture_semantics == report.capture_semantics
            && self.planner_work == report.planner_work
            && self.unicode_scalar_planner_work == report.unicode_scalar_planner_work
            && self.word_run_planner_work == report.word_run_planner_work
            && self.literal_assertions_planner_work == report.literal_assertions_planner_work
            && self.blocking_delimiter_planner_work == report.blocking_delimiter_planner_work
            && self.token_phrase_planner_work == report.token_phrase_planner_work
            && self.fixed_class_sandwich_planner_work == report.fixed_class_sandwich_planner_work
            && self.bounded_affix_planner_work == report.bounded_affix_planner_work
            && self.grapheme_scalar_dfa_planner_work == report.grapheme_scalar_dfa_planner_work
            && self.bounded_class_sequence_planner_work
                == report.bounded_class_sequence_planner_work
            && self.bounded_separated_fields_planner_work
                == report.bounded_separated_fields_planner_work
            && self.prefix_class_alternation_planner_work
                == report.prefix_class_alternation_planner_work
            && self.literal_class_run_literal_planner_work
                == report.literal_class_run_literal_planner_work
            && self.bounded_literal_pair_planner_work == report.bounded_literal_pair_planner_work
            && self.bounded_context_planner_work == report.bounded_context_planner_work
            && self.fixed_absolute_planner_work == report.fixed_absolute_planner_work
            && self.finite_planner_work == report.finite_planner_work
            && self.capture_erasure_work == report.capture_erasure_work
            && self.captures_erased == report.captures_erased
            && self.build == report.build
            && self.plan_identity == report.plan_identity
            && self.retained_capacity_bytes == report.retained_capacity_bytes
    }

    fn matches_cache(&self, cache: &AggregateCacheIdentity) -> bool {
        self.syntax_key.as_ptr() == Arc::as_ptr(&cache.syntax_key)
            && self.schema_version == cache.schema_version
            && self.operation == cache.operation
            && self.selection == cache.selection
            && self.requested_strategy == cache.requested_strategy
            && self.plan == cache.plan
            && self.continuation_strategy == cache.continuation_strategy
            && self.capture_semantics == cache.capture_semantics
            && self.plan_identity == cache.plan_identity
            && self.match_domain == cache.match_domain
            && self.build_limits == cache.build_limits
            && self.construction_stage == cache.construction_stage
    }
}

impl AggregateBuildReport {
    /// Closed identity/P/A/stage/publication receipt for this construction.
    #[must_use]
    pub const fn construction_attempt_receipt(&self) -> Option<&AggregateConstructionReceipt> {
        match self.construction_attempt.as_ref() {
            Some(evidence) => Some(&evidence.receipt),
            None => None,
        }
    }

    /// Nested receipt for the actual syntax effects consumed by this
    /// construction.
    #[must_use]
    pub const fn syntax_attempt_receipt(&self) -> Option<&fre_syntax::ParseAttemptReceipt> {
        self.syntax_attempt.as_ref()
    }

    /// Authenticate the exact source owner, nested syntax receipt, selected
    /// plan owner, schema, P/A ledger, and one-shot publication state.
    #[must_use]
    pub fn has_closed_construction_attempt(&self) -> bool {
        let (Some(evidence), Some(artifact_owner), Some(syntax)) = (
            self.construction_attempt.as_ref(),
            self.published_artifact_owner.as_ref(),
            self.syntax_attempt.as_ref(),
        ) else {
            return false;
        };
        let construction = &evidence.receipt;
        let Some(plan) = construction.published_plan.as_ref() else {
            return false;
        };
        let request = construction.identity.request_owner.request();
        let syntax_ledger_closes = construction.ledger.iter().any(|entry| {
            entry.stage == AggregateConstructionStage::SyntaxParseAdmission
                && entry.disposition == crate::AggregateConstructionStageDisposition::Completed
                && entry.effect == syntax_construction_effect(syntax, true)
        });
        construction.closes(&construction.identity, Some(plan))
            && construction.terminal == crate::AggregateConstructionTerminal::Success
            && Arc::ptr_eq(&evidence.report_seal, artifact_owner)
            && evidence.report_seal.matches_report(self)
            && self.schema_version == AGGREGATE_EXPLAIN_SCHEMA_VERSION
            && construction.identity.explain_schema_version == self.schema_version
            && request.syntax_request.has_stable_source_owner()
            && request.operation == self.operation
            && request.selection == self.selection
            && request.strategy == self.requested_strategy
            && request.build_limits == self.build_limits
            && matches!(
                &self.syntax_key.profile,
                CompatibilityProfile::RustBytes(profile) if profile == &request.profile
            )
            && request.syntax_request.authenticates_key(&self.syntax_key)
            && syntax.identity == request.syntax_request
            && syntax.terminal == fre_syntax::ParseAttemptTerminal::Success
            && syntax.authenticates_canonical()
            && syntax.identity.authenticates_key(&self.syntax_key)
            && syntax_ledger_closes
            && self.syntax.hir_nodes == syntax.actual.hir_nodes
            && self.syntax.max_depth == syntax.actual.max_depth
            && self.syntax.literal_bytes == syntax.actual.literal_bytes
            && self.syntax.class_ranges == syntax.actual.class_ranges
            && self.syntax.captures == syntax.actual.captures
            && self.syntax.repetitions == syntax.actual.repetitions
            && syntax.prospective.and_then(|prospective| {
                prospective
                    .source_bytes
                    .checked_add(syntax.actual.observed_work)
            }) == Some(self.syntax.parse_work)
            && matches!(
                (self.build_limits.admission, self.admission),
                (
                    AdmissionPolicy::Strict(_),
                    AdmissionStatus::UpstreamOraclePending,
                ) | (AdmissionPolicy::Quota(_), AdmissionStatus::QuotaChecked)
            )
            && plan.stage() == construction_stage_for_report(self)
            && construction_stage_closes_plan(plan.stage(), self.plan, self.plan_identity)
            && construction_strategy_closes_plan(
                self.requested_strategy,
                self.continuation_strategy,
                self.plan,
                self.plan_identity,
            )
            && plan.plan() == &self.plan_identity
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct AggregateRequiredInternalAnchorSeal {
    program: AggregatePlanId,
    compile: AggregateCompileAccounting,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct AggregateUrlAggregateSeal {
    program: AggregatePlanId,
    compile: AggregateCompileAccounting,
}

#[derive(Clone, Debug, Eq, PartialEq)]
#[allow(
    clippy::large_enum_variant,
    reason = "the fixed owner seal remains allocation-free and pointer-exact; boxing would add an unbudgeted allocation"
)]
enum AggregateUrlOrFixedSeal {
    Url(AggregateUrlAggregateSeal),
    Fixed(AggregateExecutionIdentity),
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct AggregateFixedAbsoluteDomainSeal {
    construction_attempt: Option<AggregateConstructionReceipt>,
    schema_version: u32,
    syntax_key: Arc<CacheKey>,
    admission: AdmissionStatus,
    syntax: ParseSummary,
    operation: AggregateOperation,
    selection: AggregatePlanSelection,
    requested_strategy: AggregateStrategy,
    build_limits: AggregateBuildLimits,
    plan: AggregatePlanKind,
    continuation_strategy: Option<AggregateStrategy>,
    capture_semantics: AggregateCaptureSemantics,
    planner_work: usize,
    unicode_scalar_planner_work: usize,
    word_run_planner_work: usize,
    literal_assertions_planner_work: usize,
    blocking_delimiter_planner_work: usize,
    token_phrase_planner_work: usize,
    fixed_class_sandwich_planner_work: usize,
    bounded_affix_planner_work: usize,
    grapheme_scalar_dfa_planner_work: usize,
    bounded_class_sequence_planner_work: usize,
    bounded_separated_fields_planner_work: usize,
    prefix_class_alternation_planner_work: usize,
    literal_class_run_literal_planner_work: usize,
    bounded_literal_pair_planner_work: usize,
    bounded_context_planner_work: usize,
    fixed_absolute_planner_work: usize,
    max_fixed_absolute_planner_work: usize,
    finite_planner_work: u64,
    capture_erasure_work: usize,
    captures_erased: usize,
    identity: AggregateFixedAbsoluteDomainIdentity,
    build: AggregateFixedAbsoluteDomainBuildAccounting,
    admission_policy: AdmissionPolicy,
    syntax_safety: SafetyEnvelope,
    guard_build_limits: FixedAbsoluteDomainBuildLimits,
    residual_build_limits: AggregateFixedAbsoluteDomainResidualBuildLimits,
    continuation_build_limits: AggregateCompileLimits,
    residual_allocation_census: Option<usize>,
    retained_capacity_bytes: usize,
}

impl AggregateFixedAbsoluteDomainSeal {
    fn matches_build_inputs(&self, limits: &AggregateBuildLimits) -> bool {
        let scalar = self.identity.kernel.descriptor.kind()
            == FixedAbsoluteDomainDescriptorKind::WholeScalarEnvelope;
        self.build_limits == *limits
            && self.admission_policy == limits.admission
            && self.syntax_safety == limits.syntax_safety
            && self.max_fixed_absolute_planner_work == limits.max_fixed_absolute_planner_work
            && self.guard_build_limits == limits.fixed_absolute
            && (!scalar
                || self.residual_build_limits == limits.fixed_absolute_residual
                    && self.continuation_build_limits == limits.continuation)
    }

    fn has_closed_construction_attempt(&self) -> bool {
        let Some(construction) = &self.construction_attempt else {
            return false;
        };
        let Some(plan) = construction.published_plan.as_ref() else {
            return false;
        };
        let request = construction.identity.request_owner.request();
        construction.closes(&construction.identity, Some(plan))
            && construction.terminal == crate::AggregateConstructionTerminal::Success
            && self.schema_version == AGGREGATE_EXPLAIN_SCHEMA_VERSION
            && construction.identity.explain_schema_version == self.schema_version
            && request.syntax_request.has_stable_source_owner()
            && plan.stage() == AggregateConstructionStage::FixedAbsolute
            && construction_stage_closes_plan(
                AggregateConstructionStage::FixedAbsolute,
                self.plan,
                AggregatePlanIdentity::FixedAbsoluteDomain(self.identity),
            )
            && plan.plan() == &AggregatePlanIdentity::FixedAbsoluteDomain(self.identity)
            && self.capture_semantics == AggregateCaptureSemantics::ErasedForWholeMatchOnly
            && self.matches_build_inputs(&self.build_limits)
            && request.operation == self.operation
            && request.selection == self.selection
            && request.strategy == self.requested_strategy
            && request.build_limits == self.build_limits
            && matches!(
                &self.syntax_key.profile,
                CompatibilityProfile::RustBytes(profile) if profile == &request.profile
            )
            && request.syntax_request.authenticates_key(&self.syntax_key)
            && construction_strategy_closes_plan(
                self.requested_strategy,
                self.continuation_strategy,
                self.plan,
                AggregatePlanIdentity::FixedAbsoluteDomain(self.identity),
            )
    }

    fn matches_public_report(&self, report: &AggregateBuildReport) -> bool {
        self.has_closed_construction_attempt()
            && report.has_closed_construction_attempt()
            && self.construction_attempt.as_ref() == report.construction_attempt_receipt()
            && self.schema_version == report.schema_version
            && self.syntax_key == report.syntax_key
            && self.admission == report.admission
            && self.syntax == report.syntax
            && self.operation == report.operation
            && self.selection == report.selection
            && self.requested_strategy == report.requested_strategy
            && self.build_limits == report.build_limits
            && self.plan == report.plan
            && self.continuation_strategy == report.continuation_strategy
            && self.capture_semantics == report.capture_semantics
            && self.planner_work == report.planner_work
            && self.unicode_scalar_planner_work == report.unicode_scalar_planner_work
            && self.word_run_planner_work == report.word_run_planner_work
            && self.literal_assertions_planner_work == report.literal_assertions_planner_work
            && self.blocking_delimiter_planner_work == report.blocking_delimiter_planner_work
            && self.token_phrase_planner_work == report.token_phrase_planner_work
            && self.fixed_class_sandwich_planner_work == report.fixed_class_sandwich_planner_work
            && self.bounded_affix_planner_work == report.bounded_affix_planner_work
            && self.grapheme_scalar_dfa_planner_work == report.grapheme_scalar_dfa_planner_work
            && self.bounded_class_sequence_planner_work
                == report.bounded_class_sequence_planner_work
            && self.bounded_separated_fields_planner_work
                == report.bounded_separated_fields_planner_work
            && self.prefix_class_alternation_planner_work
                == report.prefix_class_alternation_planner_work
            && self.literal_class_run_literal_planner_work
                == report.literal_class_run_literal_planner_work
            && self.bounded_literal_pair_planner_work == report.bounded_literal_pair_planner_work
            && self.bounded_context_planner_work == report.bounded_context_planner_work
            && u32::try_from(self.fixed_absolute_planner_work).ok()
                == Some(report.fixed_absolute_planner_work)
            && self.finite_planner_work == report.finite_planner_work
            && self.capture_erasure_work == report.capture_erasure_work
            && self.captures_erased == report.captures_erased
            && matches!(
                report.plan_identity,
                AggregatePlanIdentity::FixedAbsoluteDomain(identity)
                    if identity == self.identity
            )
            && matches!(
                report.build,
                AggregateBuildAccounting::FixedAbsoluteDomain(summary)
                    if summary == self.build.summary()
            )
            && self.retained_capacity_bytes == report.retained_capacity_bytes
    }
}

impl AggregateBuildReport {
    fn fixed_absolute_domain_owner(&self) -> Option<&AggregateExecutionIdentity> {
        match self.sealed_url_aggregate_identity.as_ref() {
            Some(AggregateUrlOrFixedSeal::Fixed(owner)) => Some(owner),
            _ => None,
        }
    }

    /// Check that all public fixed-route discriminators and resource receipts
    /// are the exact owner-local values sealed with the immutable artifacts.
    #[must_use]
    #[allow(
        clippy::too_many_lines,
        reason = "the closure proof intentionally keeps every route, owner and accounting invariant in one audit boundary"
    )]
    pub fn has_closed_fixed_absolute_domain_identity(&self) -> bool {
        match (
            self.plan,
            self.build,
            self.plan_identity,
            self.fixed_absolute_domain_owner(),
        ) {
            (
                AggregatePlanKind::FixedAbsoluteDomain,
                AggregateBuildAccounting::FixedAbsoluteDomain(summary),
                AggregatePlanIdentity::FixedAbsoluteDomain(identity),
                Some(owner),
            ) => {
                let sealed = owner.fixed_absolute_domain_seal();
                if summary != sealed.build.summary() {
                    return false;
                }
                let build = sealed.build;
                let scalar = identity.kernel.descriptor.kind()
                    == FixedAbsoluteDomainDescriptorKind::WholeScalarEnvelope;
                let operation_closed = matches!(
                    (
                        self.operation,
                        identity.kernel.operation,
                        identity.kernel.descriptor.kind(),
                    ),
                    (
                        AggregateOperation::Count,
                        fre_kernels::FixedAbsoluteDomainOperation::Count,
                        FixedAbsoluteDomainDescriptorKind::WholeByteRepeat
                            | FixedAbsoluteDomainDescriptorKind::WholeOrderedWords
                            | FixedAbsoluteDomainDescriptorKind::WholeScalarEnvelope
                            | FixedAbsoluteDomainDescriptorKind::StartMaskSequence,
                    ) | (
                        AggregateOperation::SpanSum,
                        fre_kernels::FixedAbsoluteDomainOperation::SpanSum,
                        FixedAbsoluteDomainDescriptorKind::EndMaskSequence
                            | FixedAbsoluteDomainDescriptorKind::EndOneByteMask
                            | FixedAbsoluteDomainDescriptorKind::EndGreedyClassLiteral
                            | FixedAbsoluteDomainDescriptorKind::StartOrderedPrefix
                            | FixedAbsoluteDomainDescriptorKind::StartMaskSequence,
                    )
                );
                let residual_closed = match (
                    scalar,
                    identity.residual,
                    identity.residual_strategy,
                    build.residual,
                    identity.kernel.residual,
                    self.continuation_strategy,
                ) {
                    (false, None, None, None, FixedAbsoluteDomainResidual::None, None) => true,
                    (
                        true,
                        Some(AggregateContinuationIdentity {
                            semantics: AggregateContinuationSemantics::UnicodeOnUtf8ScalarHir,
                            ..
                        }),
                        Some(identity_strategy),
                        Some(_),
                        FixedAbsoluteDomainResidual::PrepublishedContinuation,
                        Some(report_strategy),
                    ) => identity_strategy == report_strategy,
                    _ => false,
                };
                let Some(owner_bytes) = fixed_absolute_owner_bytes().ok() else {
                    return false;
                };
                let Some(owner_work) = u64::try_from(owner_bytes).ok() else {
                    return false;
                };
                let expected_guard_with_owner =
                    include_fixed_absolute_owner_guard_prospective(build.kernel.prospective)
                        .ok()
                        .zip(include_fixed_absolute_owner_guard_actual(build.kernel.actual).ok());
                let guard_with_owner_closed =
                    expected_guard_with_owner.is_some_and(|(prospective, actual)| {
                        build.guard_with_owner
                            == FixedAbsoluteDomainBuildAccounting {
                                prospective,
                                actual,
                            }
                            && fixed_guard_build_actual_fits(actual, prospective)
                            && fixed_guard_build_limit_refusal(
                                prospective,
                                sealed.guard_build_limits,
                            )
                            .is_none()
                    });
                let artifact_persistent = build.residual.map_or_else(
                    || Some(build.kernel.actual.persistent_bytes),
                    |residual| {
                        build
                            .kernel
                            .actual
                            .persistent_bytes
                            .checked_add(residual.program_bytes)
                    },
                );
                let artifact_peak = build.residual.map_or_else(
                    || Some(build.kernel.actual.peak_bytes),
                    |residual| {
                        build
                            .kernel
                            .actual
                            .persistent_bytes
                            .checked_add(residual.construction_peak_bytes)
                            .map(|co_live| co_live.max(build.kernel.actual.peak_bytes))
                    },
                );
                let expected_persistent =
                    artifact_persistent.and_then(|bytes| bytes.checked_add(owner_bytes));
                let expected_peak = artifact_peak
                    .zip(expected_persistent)
                    .map(|(peak, persistent)| peak.max(persistent));
                let expected_prospective = if scalar {
                    sealed.residual_allocation_census.and_then(|allocations| {
                        compose_fixed_residual_build_prospective(
                            build.kernel.prospective,
                            sealed.continuation_build_limits,
                            allocations,
                        )
                        .and_then(include_fixed_absolute_owner_prospective)
                        .ok()
                    })
                } else {
                    include_fixed_absolute_owner_prospective(
                        AggregateFixedAbsoluteDomainResidualBuildProspective {
                            work: build.kernel.prospective.build_work,
                            allocations: build.kernel.prospective.allocations,
                            persistent_bytes: build.kernel.prospective.persistent_bytes,
                            peak_bytes: build.kernel.prospective.peak_bytes,
                        },
                    )
                    .ok()
                };
                let expected_actual_work = build
                    .residual
                    .and_then(|residual| {
                        u64::try_from(residual.work)
                            .ok()
                            .and_then(|work| build.kernel.actual.build_work.checked_add(work))
                    })
                    .or_else(|| (!scalar).then_some(build.kernel.actual.build_work))
                    .and_then(|work| work.checked_add(owner_work));
                let expected_actual_allocations = sealed
                    .residual_allocation_census
                    .map_or_else(
                        || Some(build.kernel.actual.allocations),
                        |allocations| build.kernel.actual.allocations.checked_add(allocations),
                    )
                    .and_then(|allocations| allocations.checked_add(1));
                let prospective_admitted = fixed_residual_build_limit_refusal(
                    build.prospective,
                    sealed.residual_build_limits,
                )
                .is_none();
                operation_closed
                    && residual_closed
                    && self.schema_version == AGGREGATE_EXPLAIN_SCHEMA_VERSION
                    && self.selection == AggregatePlanSelection::Auto
                    && self.capture_semantics == AggregateCaptureSemantics::ErasedForWholeMatchOnly
                    && self.finite_planner_work == 0
                    && usize::try_from(self.fixed_absolute_planner_work)
                        .is_ok_and(|work| work <= sealed.max_fixed_absolute_planner_work)
                    && matches!(
                        &self.syntax_key.profile,
                        CompatibilityProfile::RustBytes(profile) if {
                            let mut expected = RustProfile::rebar_1_12_4();
                            expected.options.unicode = profile.options.unicode;
                            profile == &expected
                        }
                    )
                    && sealed.matches_public_report(self)
                    && owner.has_closed_fixed_construction()
                    && identity == sealed.identity
                    && build == sealed.build
                    && fixed_guard_build_actual_fits(build.kernel.actual, build.kernel.prospective)
                    && guard_with_owner_closed
                    && build.kernel.prospective.descriptor == identity.kernel.descriptor
                    && expected_prospective == Some(build.prospective)
                    && expected_actual_work == Some(build.actual.work)
                    && expected_actual_allocations == Some(build.actual.allocations)
                    && expected_persistent == Some(build.actual.persistent_bytes)
                    && expected_peak == Some(build.actual.peak_bytes)
                    && prospective_admitted
                    && build.actual.published
                    && build.actual.work <= build.prospective.work
                    && build.actual.allocations <= build.prospective.allocations
                    && build.actual.persistent_bytes <= build.prospective.persistent_bytes
                    && build.actual.peak_bytes <= build.prospective.peak_bytes
                    && self.retained_capacity_bytes == build.actual.persistent_bytes
            }
            (plan, build, identity, None) => {
                plan != AggregatePlanKind::FixedAbsoluteDomain
                    && !matches!(build, AggregateBuildAccounting::FixedAbsoluteDomain(_))
                    && !matches!(identity, AggregatePlanIdentity::FixedAbsoluteDomain(_))
            }
            _ => false,
        }
    }

    /// Authenticate one fixed absolute-domain facade identity against the
    /// construction-owned seal.
    #[must_use]
    pub fn authenticates_fixed_absolute_domain_identity(
        &self,
        identity: AggregateFixedAbsoluteDomainIdentity,
    ) -> bool {
        self.has_closed_fixed_absolute_domain_identity()
            && matches!(
                self.fixed_absolute_domain_owner(),
                Some(owner)
                    if owner.fixed_absolute_domain_seal().identity == identity
            )
    }

    /// Complete fixed-domain construction receipt retained once behind the
    /// authenticated construction owner.
    #[must_use]
    pub fn fixed_absolute_domain_build_accounting(
        &self,
    ) -> Option<&AggregateFixedAbsoluteDomainBuildAccounting> {
        let AggregateBuildAccounting::FixedAbsoluteDomain(summary) = self.build else {
            return None;
        };
        let sealed = self
            .fixed_absolute_domain_owner()?
            .fixed_absolute_domain_seal();
        (summary == sealed.build.summary()).then_some(&sealed.build)
    }

    /// Require the public URL-aggregate accounting and the private compiled
    /// artifact to be either coherently active or coherently absent.
    #[must_use]
    pub fn has_closed_url_aggregate_identity(&self) -> bool {
        let AggregateBuildAccounting::Continuation(compile) = self.build else {
            return !matches!(
                self.sealed_url_aggregate_identity,
                Some(AggregateUrlOrFixedSeal::Url(_))
            );
        };
        let absent = compile.url_aggregate_plans == 0
            && compile.url_aggregate_tlds == 0
            && compile.url_aggregate_tld_bytes == 0
            && compile.url_aggregate_build_work == 0
            && compile.url_aggregate_persistent_bytes == 0;
        match self.sealed_url_aggregate_identity.as_ref() {
            Some(AggregateUrlOrFixedSeal::Url(sealed)) => {
                compile.url_aggregate_plans == 1
                    && compile.url_aggregate_tlds > 0
                    && compile.url_aggregate_tld_bytes > 0
                    && compile.url_aggregate_build_work > 0
                    && compile.url_aggregate_persistent_bytes > 0
                    && sealed.compile == compile
                    && matches!(
                        self.plan_identity,
                        AggregatePlanIdentity::Continuation(identity)
                            if identity.program == sealed.program
                                && identity.semantics
                                    == AggregateContinuationSemantics::UnicodeOffByteBoundaries
                    )
                    && self.plan == AggregatePlanKind::ContinuationProgram
                    && self.retained_capacity_bytes == compile.program_bytes
            }
            Some(AggregateUrlOrFixedSeal::Fixed(_)) => false,
            None => absent,
        }
    }

    #[must_use]
    pub fn authenticates_url_aggregate_identity(&self) -> bool {
        self.has_closed_url_aggregate_identity()
            && matches!(
                self.sealed_url_aggregate_identity,
                Some(AggregateUrlOrFixedSeal::Url(_))
            )
    }

    /// Require the public required-anchor discriminators and private compiled
    /// artifact to be either coherently active or coherently absent.
    #[must_use]
    pub fn has_closed_required_internal_anchor_identity(&self) -> bool {
        let AggregateBuildAccounting::Continuation(compile) = self.build else {
            return self.sealed_required_internal_anchor_identity.is_none();
        };
        let absent = compile.required_internal_anchors == 0
            && compile.required_internal_anchor_bytes == 0
            && compile.required_internal_anchor_optional_stages == 0
            && compile.required_internal_anchor_build_work == 0
            && compile.required_internal_anchor_build_work_upper_bound == 0
            && compile.required_internal_anchor_persistent_bytes == 0;
        match self.sealed_required_internal_anchor_identity {
            Some(sealed) => {
                matches!(
                    self.plan_identity,
                    AggregatePlanIdentity::Continuation(identity)
                        if identity.semantics == AggregateContinuationSemantics::UnicodeOffByteBoundaries
                            && identity.program == sealed.program
                ) && self.plan == AggregatePlanKind::ContinuationProgram
                    && compile.required_internal_anchors == 1
                    && compile.required_internal_anchor_bytes > 0
                    && compile.required_internal_anchor_build_work > 0
                    && compile.required_internal_anchor_build_work
                        <= compile.required_internal_anchor_build_work_upper_bound
                    && compile.required_internal_anchor_persistent_bytes > 0
                    && compile == sealed.compile
                    && self.retained_capacity_bytes == compile.program_bytes
            }
            None => absent,
        }
    }

    #[must_use]
    pub fn authenticates_required_internal_anchor_identity(&self) -> bool {
        self.has_closed_required_internal_anchor_identity()
            && self.sealed_required_internal_anchor_identity.is_some()
    }

    /// Check that the public bounded-separated discriminators and private
    /// construction seal form one closed identity state. A report is valid
    /// either when every bounded discriminator and the seal are absent, or
    /// when all four are present and the public resource certificate exactly
    /// matches the immutable construction certificate.
    #[must_use]
    pub fn has_closed_bounded_separated_fields_identity(&self) -> bool {
        match (
            self.plan,
            self.build,
            self.plan_identity,
            self.sealed_bounded_separated_fields_identity,
        ) {
            (
                AggregatePlanKind::BoundedSeparatedFields,
                AggregateBuildAccounting::BoundedSeparatedFields(build),
                AggregatePlanIdentity::BoundedSeparatedFields(identity),
                Some(sealed),
            ) => {
                identity == sealed
                    && build == sealed.kernel.build_accounting()
                    && self.retained_capacity_bytes == build.persistent_bytes
            }
            (plan, build, identity, None) => {
                plan != AggregatePlanKind::BoundedSeparatedFields
                    && !matches!(build, AggregateBuildAccounting::BoundedSeparatedFields(_))
                    && !matches!(identity, AggregatePlanIdentity::BoundedSeparatedFields(_))
            }
            _ => false,
        }
    }

    /// Check that a bounded separated-field identity is the exact immutable
    /// certificate published with this construction report.
    #[must_use]
    pub fn authenticates_bounded_separated_fields_identity(
        &self,
        identity: AggregateBoundedSeparatedFieldsIdentity,
    ) -> bool {
        matches!(
            self.sealed_bounded_separated_fields_identity,
            Some(sealed) if sealed == identity
        )
    }
}

/// Complete equality key for a compiled aggregate operation invocation.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateCacheIdentity {
    pub schema_version: u32,
    construction_attempt: AggregateClosureEvidence<AggregateClosedConstructionEvidence>,
    artifact_owner: AggregateClosureEvidence<Arc<AggregatePublishedReportSeal>>,
    construction_stage: AggregateConstructionStage,
    pub syntax_key: Arc<CacheKey>,
    pub operation: AggregateOperation,
    pub selection: AggregatePlanSelection,
    pub requested_strategy: AggregateStrategy,
    pub plan: AggregatePlanKind,
    pub continuation_strategy: Option<AggregateStrategy>,
    pub capture_semantics: AggregateCaptureSemantics,
    pub plan_identity: AggregatePlanIdentity,
    match_domain: AggregateMatchDomainProof,
    pub build_limits: AggregateBuildLimits,
    pub execution_limits: AggregateRunLimits,
}

impl AggregateCacheIdentity {
    /// The same closed whole-construction receipt retained by the compiled
    /// artifact's build report.
    #[must_use]
    pub const fn construction_attempt_receipt(&self) -> Option<&AggregateConstructionReceipt> {
        match self.construction_attempt.as_ref() {
            Some(evidence) => Some(&evidence.receipt),
            None => None,
        }
    }

    /// Authenticate this cache identity against its exact construction owner.
    #[must_use]
    pub fn has_closed_construction_attempt(&self) -> bool {
        let (Some(evidence), Some(artifact_owner)) = (
            self.construction_attempt.as_ref(),
            self.artifact_owner.as_ref(),
        ) else {
            return false;
        };
        let construction = &evidence.receipt;
        let Some(plan) = construction.published_plan.as_ref() else {
            return false;
        };
        let request = construction.identity.request_owner.request();
        construction.closes(&construction.identity, Some(plan))
            && construction.terminal == crate::AggregateConstructionTerminal::Success
            && Arc::ptr_eq(&evidence.report_seal, artifact_owner)
            && evidence.report_seal.matches_cache(self)
            && self.schema_version == AGGREGATE_EXPLAIN_SCHEMA_VERSION
            && construction.identity.explain_schema_version == self.schema_version
            && request.syntax_request.has_stable_source_owner()
            && plan.stage() == self.construction_stage
            && construction_stage_closes_plan(
                self.construction_stage,
                self.plan,
                self.plan_identity,
            )
            && request.operation == self.operation
            && request.selection == self.selection
            && request.strategy == self.requested_strategy
            && request.build_limits == self.build_limits
            && matches!(
                &self.syntax_key.profile,
                CompatibilityProfile::RustBytes(profile) if profile == &request.profile
            )
            && request.syntax_request.authenticates_key(&self.syntax_key)
            && construction_strategy_closes_plan(
                self.requested_strategy,
                self.continuation_strategy,
                self.plan,
                self.plan_identity,
            )
            && plan.plan() == &self.plan_identity
    }
}

/// Physical direct reducer selected before an aggregate invocation can inspect
/// source. Packed, dense, and sparse finite reducers remain distinct.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum AggregateDirectRoute {
    ExactLiteral,
    UnicodeScalar,
    WordRun,
    LiteralAssertions,
    BlockingDelimiter,
    TokenPhrase,
    FixedClassSandwich,
    GraphemeScalarDfa,
    BoundedClassSequence,
    BoundedSeparatedFields,
    PrefixClassAlternation,
    LiteralClassRunLiteral,
    ReverseInner,
    BoundedLiteralPair,
    BoundedContext,
    PackedFiniteLiteral,
    DenseFiniteLiteral,
    SparseFiniteLiteral,
    GuardedAsciiWord,
    GuardedUnicodeWord,
    FixedPredicateWord64,
}

/// Permitted action after a direct aggregate route has been published.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AggregateDirectDeclaredFallback {
    /// A refusal or fault is terminal; no alternate plan may read source.
    None,
}

/// Compact route identity owned by one published direct aggregate plan.
///
/// The syntax-key `Arc` is allocated by parsing and already retained by the
/// build report. A private `Weak` handle to that allocation is the exact
/// provenance root: it adds neither an allocation nor a strong source-key
/// clone, and it prevents address reuse while a detached owner seal exists.
/// The complete structural identity remains in the colocated public cache
/// identity and is authenticated by [`AggregateDirectOwnerSeal::authenticates`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateDirectRouteIdentity {
    pub schema_version: u32,
    pub operation: AggregateOperation,
    pub selection: AggregatePlanSelection,
    pub route: AggregateDirectRoute,
    pub plan: AggregatePlanKind,
    pub capture_semantics: AggregateCaptureSemantics,
    pub plan_identity: AggregatePlanIdentity,
    pub build_limits: AggregateBuildLimits,
    pub algorithm_version: u32,
    pub accounting_version: u32,
    pub declared_fallback: AggregateDirectDeclaredFallback,
}

impl AggregateDirectRouteIdentity {
    fn closes_cache_fields(&self, cache: &AggregateCacheIdentity) -> bool {
        self.schema_version == AGGREGATE_EXPLAIN_SCHEMA_VERSION
            && cache.schema_version == self.schema_version
            && self.operation == cache.operation
            && self.selection == cache.selection
            && self.plan == cache.plan
            && cache.continuation_strategy.is_none()
            && self.capture_semantics == cache.capture_semantics
            && self.plan_identity == cache.plan_identity
            && self.build_limits == cache.build_limits
            && self.algorithm_version == AGGREGATE_DIRECT_OWNER_ALGORITHM_VERSION
            && self.accounting_version == AGGREGATE_DIRECT_OWNER_ACCOUNTING_VERSION
            && self.declared_fallback == AggregateDirectDeclaredFallback::None
            && cache.has_closed_construction_attempt()
            && direct_route_matches_plan(self.route, cache.plan, cache.plan_identity)
            && direct_plan_operation_closes(cache)
    }
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "one exhaustive Copy identity match keeps every physical direct route at one authentication boundary"
)]
fn direct_route_matches_plan(
    route: AggregateDirectRoute,
    plan: AggregatePlanKind,
    identity: AggregatePlanIdentity,
) -> bool {
    match (route, plan, identity) {
        (
            AggregateDirectRoute::ExactLiteral,
            AggregatePlanKind::ExactLiteral,
            AggregatePlanIdentity::ExactLiteral(_),
        )
        | (
            AggregateDirectRoute::UnicodeScalar,
            AggregatePlanKind::UnicodeScalarClass,
            AggregatePlanIdentity::UnicodeScalar(_),
        )
        | (
            AggregateDirectRoute::WordRun,
            AggregatePlanKind::WordRun,
            AggregatePlanIdentity::WordRun(_),
        )
        | (
            AggregateDirectRoute::LiteralAssertions,
            AggregatePlanKind::LiteralAssertions,
            AggregatePlanIdentity::LiteralAssertions(_),
        )
        | (
            AggregateDirectRoute::BlockingDelimiter,
            AggregatePlanKind::BlockingDelimiter,
            AggregatePlanIdentity::BlockingDelimiter(_),
        )
        | (
            AggregateDirectRoute::TokenPhrase,
            AggregatePlanKind::TokenPhrase,
            AggregatePlanIdentity::TokenPhrase(_),
        )
        | (
            AggregateDirectRoute::FixedClassSandwich,
            AggregatePlanKind::FixedClassSandwich,
            AggregatePlanIdentity::FixedClassSandwich(_),
        )
        | (
            AggregateDirectRoute::GraphemeScalarDfa,
            AggregatePlanKind::GraphemeScalarDfa,
            AggregatePlanIdentity::GraphemeScalarDfa(_),
        )
        | (
            AggregateDirectRoute::BoundedClassSequence,
            AggregatePlanKind::BoundedClassSequence,
            AggregatePlanIdentity::BoundedClassSequence(_),
        )
        | (
            AggregateDirectRoute::BoundedSeparatedFields,
            AggregatePlanKind::BoundedSeparatedFields,
            AggregatePlanIdentity::BoundedSeparatedFields(_),
        )
        | (
            AggregateDirectRoute::PrefixClassAlternation,
            AggregatePlanKind::PrefixClassAlternation,
            AggregatePlanIdentity::PrefixClassAlternation(_),
        )
        | (
            AggregateDirectRoute::LiteralClassRunLiteral,
            AggregatePlanKind::LiteralClassRunLiteral,
            AggregatePlanIdentity::LiteralClassRunLiteral(_),
        )
        | (
            AggregateDirectRoute::ReverseInner,
            AggregatePlanKind::ReverseInner,
            AggregatePlanIdentity::ReverseInner(_),
        )
        | (
            AggregateDirectRoute::BoundedLiteralPair,
            AggregatePlanKind::BoundedLiteralPair,
            AggregatePlanIdentity::BoundedLiteralPair(_),
        )
        | (
            AggregateDirectRoute::BoundedContext,
            AggregatePlanKind::BoundedContext,
            AggregatePlanIdentity::BoundedContext(_),
        )
        | (
            AggregateDirectRoute::GuardedAsciiWord,
            AggregatePlanKind::GuardedAsciiWordDictionary,
            AggregatePlanIdentity::GuardedAsciiWord(_),
        )
        | (
            AggregateDirectRoute::GuardedUnicodeWord,
            AggregatePlanKind::GuardedUnicodeWordLiteralSet,
            AggregatePlanIdentity::GuardedUnicodeWord(_),
        )
        | (
            AggregateDirectRoute::FixedPredicateWord64,
            AggregatePlanKind::FixedPredicateWord64,
            AggregatePlanIdentity::FixedPredicateWord64(_),
        ) => true,
        (
            AggregateDirectRoute::PackedFiniteLiteral,
            AggregatePlanKind::PackedFiniteLiteral,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) => packed_finite_identity_closes_native(&identity),
        (
            AggregateDirectRoute::DenseFiniteLiteral,
            AggregatePlanKind::FiniteLiteralDfa,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) => {
            identity.algorithm == ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && identity.packed_operation_identity.is_none()
        }
        (
            AggregateDirectRoute::SparseFiniteLiteral,
            AggregatePlanKind::FiniteLiteralDfa,
            AggregatePlanIdentity::FiniteLiteral(identity),
        ) => {
            identity.algorithm == SPARSE_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && identity.packed_operation_identity.is_none()
        }
        _ => false,
    }
}

fn direct_operation_id_closes(
    operation: AggregateOperation,
    operation_id: &str,
    count_id: &str,
    span_sum_id: Option<&str>,
) -> bool {
    match operation {
        AggregateOperation::Compile | AggregateOperation::Count => operation_id == count_id,
        AggregateOperation::SpanSum => span_sum_id == Some(operation_id),
        AggregateOperation::Spans => false,
    }
}

fn packed_finite_identity_closes_native(identity: &AggregateFiniteLiteralIdentity) -> bool {
    let (expected_operation, expected_plan_id, bounded_prefix) = match identity.operation {
        PACKED_ORDERED_LITERAL_COUNT_PLAN_ID => (
            OrderedLiteralAggregateOperation::Count,
            PACKED_ORDERED_LITERAL_COUNT_PLAN_ID,
            false,
        ),
        PACKED_ORDERED_LITERAL_SPAN_SUM_PLAN_ID => (
            OrderedLiteralAggregateOperation::SpanSum,
            PACKED_ORDERED_LITERAL_SPAN_SUM_PLAN_ID,
            false,
        ),
        PACKED_BOUNDED_PREFIX_LITERAL_COUNT_PLAN_ID => (
            OrderedLiteralAggregateOperation::Count,
            PACKED_BOUNDED_PREFIX_LITERAL_COUNT_PLAN_ID,
            true,
        ),
        _ => return false,
    };
    identity.algorithm == PACKED_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
        && (identity.semantics == AggregateFiniteLiteralSemantics::UnicodeOffGreedyBoundedDotPrefix)
            == bounded_prefix
        && identity.packed_operation_identity.is_some_and(|native| {
            native.algorithm_id == PACKED_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && native.plan_id == expected_plan_id
                && native.operation == expected_operation
                && native.bounded_prefix.is_some() == bounded_prefix
        })
}

fn word_run_direct_identity_closes(
    operation: AggregateOperation,
    identity: AggregateWordRunIdentity,
) -> bool {
    let kernel = identity.kernel;
    let shared = kernel.greedy && kernel.non_overlapping;
    let semantic = match identity.semantics {
        AggregateWordRunSemantics::AsciiWordBytes => {
            kernel.plan_id == unicode_word_run::ASCII_PLAN_ID
                && kernel.minimum_scalars > 0
                && kernel.fixed_chunk_bytes.is_none()
                && kernel.canonical_class_words == [0; 4]
                && !kernel.unicode
                && matches!(
                    (kernel.topology, kernel.complete_word_boundaries,),
                    (
                        unicode_word_run::WordRunTopology::CompleteWordBoundaries,
                        true,
                    ) | (unicode_word_run::WordRunTopology::BareGreedyRoot, false)
                )
                && kernel.invalid_bytes_are_non_word
                && !kernel.arbitrary_bytes_are_classified
        }
        AggregateWordRunSemantics::UnicodeWordScalarsInvalidBytesNonWord => {
            kernel.plan_id == unicode_word_run::UNICODE_PLAN_ID
                && kernel.minimum_scalars > 0
                && kernel.fixed_chunk_bytes.is_none()
                && kernel.canonical_class_words == [0; 4]
                && kernel.unicode
                && matches!(
                    (kernel.topology, kernel.complete_word_boundaries,),
                    (
                        unicode_word_run::WordRunTopology::CompleteWordBoundaries,
                        true,
                    ) | (unicode_word_run::WordRunTopology::BareGreedyRoot, false)
                )
                && kernel.invalid_bytes_are_non_word
                && !kernel.arbitrary_bytes_are_classified
        }
        AggregateWordRunSemantics::UnicodeOffFixedWidthByteClassChunks => {
            kernel.plan_id == unicode_word_run::FIXED_CLASS_CHUNKS_PLAN_ID
                && kernel.minimum_scalars == 0
                && kernel.fixed_chunk_bytes.is_some_and(|width| width > 64)
                && kernel.canonical_class_words != [0; 4]
                && !kernel.unicode
                && kernel.topology == unicode_word_run::WordRunTopology::FixedClassChunks
                && !kernel.complete_word_boundaries
                && !kernel.invalid_bytes_are_non_word
                && kernel.arbitrary_bytes_are_classified
        }
    };
    let operation_closes = if kernel.plan_id == unicode_word_run::FIXED_CLASS_CHUNKS_PLAN_ID {
        direct_operation_id_closes(
            operation,
            kernel.operation_id,
            unicode_word_run::FIXED_CLASS_CHUNKS_COUNT_OPERATION_ID,
            Some(unicode_word_run::FIXED_CLASS_CHUNKS_SPAN_SUM_OPERATION_ID),
        )
    } else {
        direct_operation_id_closes(
            operation,
            kernel.operation_id,
            unicode_word_run::AGGREGATE_COUNT_OPERATION_ID,
            Some(unicode_word_run::AGGREGATE_SPAN_SUM_OPERATION_ID),
        )
    };
    shared && semantic && operation_closes
}

const fn exact_literal_operation(
    operation: AggregateOperation,
) -> Option<LiteralAggregateOperation> {
    match operation {
        AggregateOperation::Compile | AggregateOperation::Count => {
            Some(LiteralAggregateOperation::Count)
        }
        AggregateOperation::SpanSum => Some(LiteralAggregateOperation::SpanSum),
        AggregateOperation::Spans => None,
    }
}

fn exact_literal_direct_operation_closes(
    operation: AggregateOperation,
    identity: LiteralAggregateOperationIdentity,
) -> bool {
    exact_literal_operation(operation)
        .is_some_and(|operation| identity.authenticates_operation(operation))
}

fn unicode_scalar_direct_operation_closes(
    operation: AggregateOperation,
    identity: UnicodeScalarAggregateOperationIdentity,
) -> bool {
    let expected_operation = match operation {
        AggregateOperation::Compile | AggregateOperation::Count => {
            UnicodeScalarAggregateOperation::Count
        }
        AggregateOperation::SpanSum => UnicodeScalarAggregateOperation::SpanSum,
        AggregateOperation::Spans => return false,
    };
    identity
        == UnicodeScalarAggregateOperationIdentity::for_repetition(
            expected_operation,
            identity.repetition,
        )
        || (identity.repetition == UnicodeScalarAggregateRepetition::ExactlyOne
            && identity
                == UnicodeScalarAggregateOperationIdentity::for_dispatched_operation(
                    expected_operation,
                ))
}

#[allow(
    clippy::too_many_lines,
    reason = "one exhaustive closure boundary keeps all direct operation identities adjacent"
)]
fn direct_plan_operation_closes(cache: &AggregateCacheIdentity) -> bool {
    match cache.plan_identity {
        AggregatePlanIdentity::ExactLiteral(identity) => {
            exact_literal_direct_operation_closes(cache.operation, identity.kernel)
        }
        AggregatePlanIdentity::UnicodeScalar(identity) => {
            unicode_scalar_direct_operation_closes(cache.operation, identity.kernel)
        }
        AggregatePlanIdentity::WordRun(identity) => {
            word_run_direct_identity_closes(cache.operation, identity)
        }
        AggregatePlanIdentity::LiteralAssertions(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            LITERAL_ASSERTIONS_COUNT_OPERATION_ID,
            Some(LITERAL_ASSERTIONS_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::BlockingDelimiter(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            BLOCKING_DELIMITER_COUNT_OPERATION_ID,
            Some(BLOCKING_DELIMITER_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::TokenPhrase(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            TOKEN_PHRASE_COUNT_OPERATION_ID,
            Some(TOKEN_PHRASE_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::FixedClassSandwich(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            FIXED_CLASS_SANDWICH_COUNT_OPERATION_ID,
            Some(FIXED_CLASS_SANDWICH_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::GraphemeScalarDfa(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            GRAPHEME_SCALAR_DFA_COUNT_OPERATION_ID,
            Some(GRAPHEME_SCALAR_DFA_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::BoundedClassSequence(identity) => direct_operation_id_closes(
            cache.operation,
            identity.operation_id,
            BOUNDED_CLASS_SEQUENCE_COUNT_OPERATION_ID,
            None,
        ),
        AggregatePlanIdentity::BoundedSeparatedFields(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            BOUNDED_SEPARATED_FIELDS_COUNT_OPERATION_ID,
            None,
        ),
        AggregatePlanIdentity::PrefixClassAlternation(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            PREFIX_CLASS_ALTERNATION_COUNT_OPERATION_ID,
            Some(PREFIX_CLASS_ALTERNATION_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::LiteralClassRunLiteral(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            LITERAL_CLASS_RUN_LITERAL_COUNT_OPERATION_ID,
            Some(LITERAL_CLASS_RUN_LITERAL_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::ReverseInner(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            REVERSE_INNER_COUNT_OPERATION_ID,
            Some(REVERSE_INNER_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::BoundedLiteralPair(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            BOUNDED_LITERAL_PAIR_COUNT_OPERATION_ID,
            Some(BOUNDED_LITERAL_PAIR_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::BoundedContext(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            BOUNDED_CONTEXT_COUNT_OPERATION_ID,
            Some(BOUNDED_CONTEXT_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::FiniteLiteral(identity) => match identity.algorithm {
            PACKED_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID => {
                packed_finite_identity_closes_native(&identity)
                    && if identity.operation == PACKED_BOUNDED_PREFIX_LITERAL_COUNT_PLAN_ID {
                        direct_operation_id_closes(
                            cache.operation,
                            identity.operation,
                            PACKED_BOUNDED_PREFIX_LITERAL_COUNT_PLAN_ID,
                            None,
                        )
                    } else {
                        direct_operation_id_closes(
                            cache.operation,
                            identity.operation,
                            PACKED_ORDERED_LITERAL_COUNT_PLAN_ID,
                            Some(PACKED_ORDERED_LITERAL_SPAN_SUM_PLAN_ID),
                        )
                    }
            }
            ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID => {
                identity.packed_operation_identity.is_none()
                    && direct_operation_id_closes(
                        cache.operation,
                        identity.operation,
                        ORDERED_LITERAL_COUNT_PLAN_ID,
                        Some(ORDERED_LITERAL_SPAN_SUM_PLAN_ID),
                    )
            }
            SPARSE_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID => {
                identity.packed_operation_identity.is_none()
                    && direct_operation_id_closes(
                        cache.operation,
                        identity.operation,
                        SPARSE_ORDERED_LITERAL_COUNT_PLAN_ID,
                        Some(SPARSE_ORDERED_LITERAL_SPAN_SUM_PLAN_ID),
                    )
            }
            _ => false,
        },
        AggregatePlanIdentity::GuardedAsciiWord(identity) => direct_operation_id_closes(
            cache.operation,
            identity.operation,
            guarded_ascii_word::COUNT_OPERATION_ID,
            Some(guarded_ascii_word::SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::GuardedUnicodeWord(identity) => direct_operation_id_closes(
            cache.operation,
            identity.kernel.operation_id,
            guarded_unicode_word::COUNT_OPERATION_ID,
            Some(guarded_unicode_word::SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::FixedPredicateWord64(identity) => direct_operation_id_closes(
            cache.operation,
            identity.operation_id,
            FIXED_PREDICATE_WORD64_COUNT_OPERATION_ID,
            Some(FIXED_PREDICATE_WORD64_SPAN_SUM_OPERATION_ID),
        ),
        AggregatePlanIdentity::FixedAbsoluteDomain(_) | AggregatePlanIdentity::Continuation(_) => {
            false
        }
    }
}

#[allow(
    clippy::too_many_lines,
    reason = "one exhaustive closure boundary keeps all direct route identities adjacent"
)]
fn exact_literal_details_close_cache(
    cache: &AggregateCacheIdentity,
    identity: AggregateExactLiteralIdentity,
    details: &AggregateExactLiteralExecutionDetails,
) -> bool {
    let accounting = &details.accounting;
    let Some(construction_build) = details.construction.build_accounting() else {
        return false;
    };
    let expected_origin = LiteralAggregatePlanOrigin::from_external_address(
        Arc::as_ptr(&cache.syntax_key).cast::<()>().addr(),
    );
    let expected_invocation = LiteralAggregateReduceInvocation {
        haystack_bytes: accounting.upper_bounds.haystack_bytes,
        build: construction_build,
        plan_origin: details.construction.origin,
        limits: cache.execution_limits.exact_literal,
    };
    Weak::ptr_eq(
        &details.syntax_provenance,
        &Arc::downgrade(&cache.syntax_key),
    ) && expected_origin == Some(details.construction.origin)
        && details.construction.origin.is_bound()
        && accounting.authenticates(identity.kernel, expected_invocation)
        && exact_literal_direct_operation_closes(cache.operation, accounting.identity)
        && accounting.closes_receipt(&details.receipt)
        && details.receipt.authenticates_canonical()
        && details.receipt.prospective == Some(accounting.upper_bounds)
        && accounting.invocation.haystack_bytes == accounting.upper_bounds.haystack_bytes
        && accounting.invocation.build.needle_bytes == accounting.upper_bounds.needle_bytes
        && accounting.invocation.build.persistent_bytes == accounting.upper_bounds.persistent_bytes
        && accounting.upper_bounds.operation_allocations == 0
        && accounting.actual.operation_allocations == 0
        && accounting.actual_allocations == 0
        && details.receipt.actual.operation_allocations == 0
        && details.receipt.actual_allocations == 0
        && accounting.retains_bounded_actual()
        && details.receipt.retains_bounded_actual()
}

#[allow(
    clippy::too_many_lines,
    reason = "one exhaustive closure boundary keeps all direct route identities adjacent"
)]
fn direct_details_close_cache(
    cache: &AggregateCacheIdentity,
    details: &AggregateExecutionDetails,
) -> bool {
    match (&cache.plan_identity, details) {
        (
            AggregatePlanIdentity::ExactLiteral(identity),
            AggregateExecutionDetails::ExactLiteral(details),
        ) => exact_literal_details_close_cache(cache, *identity, details),
        (
            AggregatePlanIdentity::UnicodeScalar(identity),
            AggregateExecutionDetails::UnicodeScalar(accounting),
        ) => {
            identity.kernel == accounting.identity
                && unicode_scalar_direct_operation_closes(cache.operation, identity.kernel)
        }
        (
            AggregatePlanIdentity::WordRun(identity),
            AggregateExecutionDetails::WordRun(accounting),
        ) => {
            identity.kernel == accounting.identity
                && word_run_direct_identity_closes(cache.operation, *identity)
        }
        (
            AggregatePlanIdentity::LiteralAssertions(identity),
            AggregateExecutionDetails::LiteralAssertions(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    LITERAL_ASSERTIONS_COUNT_OPERATION_ID,
                    Some(LITERAL_ASSERTIONS_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::BlockingDelimiter(identity),
            AggregateExecutionDetails::BlockingDelimiter(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    BLOCKING_DELIMITER_COUNT_OPERATION_ID,
                    Some(BLOCKING_DELIMITER_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::TokenPhrase(identity),
            AggregateExecutionDetails::TokenPhrase(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    TOKEN_PHRASE_COUNT_OPERATION_ID,
                    Some(TOKEN_PHRASE_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::FixedClassSandwich(identity),
            AggregateExecutionDetails::FixedClassSandwich(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    FIXED_CLASS_SANDWICH_COUNT_OPERATION_ID,
                    Some(FIXED_CLASS_SANDWICH_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::GraphemeScalarDfa(identity),
            AggregateExecutionDetails::GraphemeScalarDfa(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    GRAPHEME_SCALAR_DFA_COUNT_OPERATION_ID,
                    Some(GRAPHEME_SCALAR_DFA_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::BoundedClassSequence(identity),
            AggregateExecutionDetails::BoundedClassSequence(accounting),
        ) => {
            identity == &accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.operation_id,
                    BOUNDED_CLASS_SEQUENCE_COUNT_OPERATION_ID,
                    None,
                )
        }
        (
            AggregatePlanIdentity::BoundedSeparatedFields(identity),
            AggregateExecutionDetails::BoundedSeparatedFields(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    BOUNDED_SEPARATED_FIELDS_COUNT_OPERATION_ID,
                    None,
                )
        }
        (
            AggregatePlanIdentity::PrefixClassAlternation(identity),
            AggregateExecutionDetails::PrefixClassAlternation(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    PREFIX_CLASS_ALTERNATION_COUNT_OPERATION_ID,
                    Some(PREFIX_CLASS_ALTERNATION_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::LiteralClassRunLiteral(identity),
            AggregateExecutionDetails::LiteralClassRunLiteral(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    LITERAL_CLASS_RUN_LITERAL_COUNT_OPERATION_ID,
                    Some(LITERAL_CLASS_RUN_LITERAL_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::ReverseInner(identity),
            AggregateExecutionDetails::ReverseInner(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    REVERSE_INNER_COUNT_OPERATION_ID,
                    Some(REVERSE_INNER_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::BoundedLiteralPair(identity),
            AggregateExecutionDetails::BoundedLiteralPair(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    BOUNDED_LITERAL_PAIR_COUNT_OPERATION_ID,
                    Some(BOUNDED_LITERAL_PAIR_SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::BoundedContext(identity),
            AggregateExecutionDetails::BoundedContext(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    BOUNDED_CONTEXT_COUNT_OPERATION_ID,
                    None,
                )
        }
        (
            AggregatePlanIdentity::BoundedContext(identity),
            AggregateExecutionDetails::BoundedContextSpanSum(accounting),
        ) => {
            identity.kernel == accounting.identity
                && cache.operation == AggregateOperation::SpanSum
                && identity.kernel.operation_id == BOUNDED_CONTEXT_SPAN_SUM_OPERATION_ID
        }
        (
            AggregatePlanIdentity::FiniteLiteral(identity),
            AggregateExecutionDetails::PackedFiniteLiteral {
                operation_identity, ..
            },
        ) => {
            packed_finite_identity_closes_native(identity)
                && identity.packed_operation_identity == Some(*operation_identity)
                && if identity.operation == PACKED_BOUNDED_PREFIX_LITERAL_COUNT_PLAN_ID {
                    direct_operation_id_closes(
                        cache.operation,
                        identity.operation,
                        PACKED_BOUNDED_PREFIX_LITERAL_COUNT_PLAN_ID,
                        None,
                    )
                } else {
                    direct_operation_id_closes(
                        cache.operation,
                        identity.operation,
                        PACKED_ORDERED_LITERAL_COUNT_PLAN_ID,
                        Some(PACKED_ORDERED_LITERAL_SPAN_SUM_PLAN_ID),
                    )
                }
        }
        (
            AggregatePlanIdentity::FiniteLiteral(identity),
            AggregateExecutionDetails::FiniteLiteral { .. },
        ) => {
            identity.algorithm == ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && identity.packed_operation_identity.is_none()
                && direct_operation_id_closes(
                    cache.operation,
                    identity.operation,
                    ORDERED_LITERAL_COUNT_PLAN_ID,
                    Some(ORDERED_LITERAL_SPAN_SUM_PLAN_ID),
                )
        }
        (
            AggregatePlanIdentity::FiniteLiteral(identity),
            AggregateExecutionDetails::SparseFiniteLiteral { .. },
        ) => {
            identity.algorithm == SPARSE_ORDERED_LITERAL_AGGREGATE_ALGORITHM_ID
                && identity.packed_operation_identity.is_none()
                && direct_operation_id_closes(
                    cache.operation,
                    identity.operation,
                    SPARSE_ORDERED_LITERAL_COUNT_PLAN_ID,
                    Some(SPARSE_ORDERED_LITERAL_SPAN_SUM_PLAN_ID),
                )
        }
        (
            AggregatePlanIdentity::GuardedAsciiWord(identity),
            AggregateExecutionDetails::GuardedAsciiWord(accounting),
        ) => {
            identity.operation == accounting.operation_id
                && direct_operation_id_closes(
                    cache.operation,
                    identity.operation,
                    guarded_ascii_word::COUNT_OPERATION_ID,
                    Some(guarded_ascii_word::SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::GuardedUnicodeWord(identity),
            AggregateExecutionDetails::GuardedUnicodeWord(accounting),
        ) => {
            identity.kernel == accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.kernel.operation_id,
                    guarded_unicode_word::COUNT_OPERATION_ID,
                    Some(guarded_unicode_word::SPAN_SUM_OPERATION_ID),
                )
        }
        (
            AggregatePlanIdentity::FixedPredicateWord64(identity),
            AggregateExecutionDetails::FixedPredicateWord64(accounting),
        ) => {
            identity == &accounting.identity
                && direct_operation_id_closes(
                    cache.operation,
                    identity.operation_id,
                    FIXED_PREDICATE_WORD64_COUNT_OPERATION_ID,
                    Some(FIXED_PREDICATE_WORD64_SPAN_SUM_OPERATION_ID),
                )
        }
        _ => false,
    }
}

/// Opaque construction provenance for one direct aggregate route.
///
/// Equality is exact syntax-owner provenance, not structural cache identity.
/// Clones of one compiled aggregate plan keep the same owner, while another
/// construction of the same pattern receives a different syntax-key `Arc`.
#[derive(Clone, Debug)]
pub struct AggregateDirectOwnerSeal {
    syntax_provenance: Weak<CacheKey>,
    identity: AggregateDirectRouteIdentity,
    authenticated_execution_limits: AggregateRunLimits,
}

impl PartialEq for AggregateDirectOwnerSeal {
    fn eq(&self, other: &Self) -> bool {
        Weak::ptr_eq(&self.syntax_provenance, &other.syntax_provenance)
            && self.identity == other.identity
    }
}

impl Eq for AggregateDirectOwnerSeal {}

impl AggregateDirectOwnerSeal {
    fn from_cache_identity(
        cache: &AggregateCacheIdentity,
        route: AggregateDirectRoute,
    ) -> Option<Self> {
        if !direct_route_matches_plan(route, cache.plan, cache.plan_identity)
            || cache.continuation_strategy.is_some()
            || !direct_plan_operation_closes(cache)
        {
            return None;
        }
        Some(Self {
            syntax_provenance: Arc::downgrade(&cache.syntax_key),
            authenticated_execution_limits: cache.execution_limits,
            identity: AggregateDirectRouteIdentity {
                schema_version: cache.schema_version,
                operation: cache.operation,
                selection: cache.selection,
                route,
                plan: cache.plan,
                capture_semantics: cache.capture_semantics,
                plan_identity: cache.plan_identity,
                build_limits: cache.build_limits,
                algorithm_version: AGGREGATE_DIRECT_OWNER_ALGORITHM_VERSION,
                accounting_version: AGGREGATE_DIRECT_OWNER_ACCOUNTING_VERSION,
                declared_fallback: AggregateDirectDeclaredFallback::None,
            },
        })
    }

    /// Compact immutable route identity owned by this construction.
    #[must_use]
    pub const fn identity(&self) -> &AggregateDirectRouteIdentity {
        &self.identity
    }

    fn closes_cache_identity(&self, cache: &AggregateCacheIdentity) -> bool {
        self.syntax_provenance.as_ptr() == Arc::as_ptr(&cache.syntax_key)
            && self.authenticated_execution_limits == cache.execution_limits
            && self.identity.closes_cache_fields(cache)
    }
}

/// Complete source identity for one direct aggregate invocation.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateDirectInvocation {
    pub haystack_len: usize,
    pub range: Range<usize>,
    pub operation: AggregateOperation,
}

/// Authenticated terminal disposition of a direct reducer attempt.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AggregateDirectAttemptTerminal {
    /// The selected direct route completed without fallback.
    Success,
    /// The selected direct route refused or faulted without fallback.
    Failure,
}

struct AggregateAotBindingEncoder {
    digest: Sha256,
    bytes_hashed: u64,
    byte_count_overflowed: bool,
}

impl AggregateAotBindingEncoder {
    fn new() -> Self {
        Self {
            digest: Sha256::new(),
            bytes_hashed: 0,
            byte_count_overflowed: false,
        }
    }

    fn raw(&mut self, bytes: &[u8]) {
        match u64::try_from(bytes.len())
            .ok()
            .and_then(|additional| self.bytes_hashed.checked_add(additional))
        {
            Some(total) => self.bytes_hashed = total,
            None => self.byte_count_overflowed = true,
        }
        self.digest.update(bytes);
    }

    fn bytes(&mut self, bytes: &[u8]) -> Option<()> {
        self.u64(u64::try_from(bytes.len()).ok()?);
        self.raw(bytes);
        Some(())
    }

    fn string(&mut self, value: &str) -> Option<()> {
        self.bytes(value.as_bytes())
    }

    fn boolean(&mut self, value: bool) {
        self.u8(u8::from(value));
    }

    fn u8(&mut self, value: u8) {
        self.raw(&[value]);
    }

    fn u16(&mut self, value: u16) {
        self.raw(&value.to_le_bytes());
    }

    fn u32(&mut self, value: u32) {
        self.raw(&value.to_le_bytes());
    }

    fn u64(&mut self, value: u64) {
        self.raw(&value.to_le_bytes());
    }

    fn usize(&mut self, value: usize) -> Option<()> {
        self.u64(u64::try_from(value).ok()?);
        Some(())
    }

    fn finish(self) -> Option<([u8; 32], u64)> {
        if self.byte_count_overflowed {
            None
        } else {
            Some((self.digest.finalize().into(), self.bytes_hashed))
        }
    }
}

struct AggregateAotPlanningEncoder {
    digest: Sha256,
    bytes_hashed: u64,
}

impl AggregateAotPlanningEncoder {
    fn new() -> Self {
        Self {
            digest: Sha256::new(),
            bytes_hashed: 0,
        }
    }

    fn raw(&mut self, bytes: &[u8]) -> Option<()> {
        self.bytes_hashed = self
            .bytes_hashed
            .checked_add(u64::try_from(bytes.len()).ok()?)?;
        self.digest.update(bytes);
        Some(())
    }

    fn u8(&mut self, value: u8) -> Option<()> {
        self.raw(&[value])
    }

    fn bytes(&mut self, value: &[u8]) -> Option<()> {
        self.u64(u64::try_from(value.len()).ok()?)?;
        self.raw(value)
    }

    fn u32(&mut self, value: u32) -> Option<()> {
        self.raw(&value.to_le_bytes())
    }

    fn u64(&mut self, value: u64) -> Option<()> {
        self.raw(&value.to_le_bytes())
    }

    fn usize(&mut self, value: usize) -> Option<()> {
        self.u64(u64::try_from(value).ok()?)
    }

    fn boolean(&mut self, value: bool) -> Option<()> {
        self.u8(u8::from(value))
    }

    fn finish(self) -> ([u8; 32], u64) {
        (self.digest.finalize().into(), self.bytes_hashed)
    }
}

fn encode_aot_upstream_revision(
    encoder: &mut AggregateAotBindingEncoder,
    revision: UpstreamRevision,
) -> Option<()> {
    let tag = match revision {
        UpstreamRevision::RustRegex1_12_4_7b96fdc => 0,
        UpstreamRevision::RustRegexAutomata0_4_14_5e195de => 1,
        UpstreamRevision::RustRegexSyntax0_8_11_1401679 => 2,
        UpstreamRevision::Rebar463d00f => 3,
        UpstreamRevision::Re2_972a15c => 4,
    };
    encoder.u8(tag);
    encoder.string(revision.commit())
}

fn encode_aot_package_identity(
    encoder: &mut AggregateAotBindingEncoder,
    identity: PackageIdentity,
) -> Option<()> {
    encoder.u16(identity.version.major);
    encoder.u16(identity.version.minor);
    encoder.u16(identity.version.patch);
    encoder.string(identity.checksum)?;
    encode_aot_upstream_revision(encoder, identity.vcs_revision)
}

fn encode_aot_unicode_version(encoder: &mut AggregateAotBindingEncoder, version: UnicodeVersion) {
    encoder.u16(version.major);
    encoder.u16(version.minor);
    encoder.u16(version.patch);
}

fn encode_aot_unicode_features(
    encoder: &mut AggregateAotBindingEncoder,
    features: RustUnicodeFeatures,
) -> Option<()> {
    let tag = if features == RustUnicodeFeatures::NONE {
        0
    } else if features == RustUnicodeFeatures::ALL {
        1
    } else if features == RustUnicodeFeatures::AGE {
        2
    } else if features == RustUnicodeFeatures::BOOL {
        3
    } else if features == RustUnicodeFeatures::CASE {
        4
    } else if features == RustUnicodeFeatures::GENCAT {
        5
    } else if features == RustUnicodeFeatures::PERL {
        6
    } else if features == RustUnicodeFeatures::SCRIPT {
        7
    } else if features == RustUnicodeFeatures::SEGMENT {
        8
    } else {
        return None;
    };
    encoder.u8(tag);
    Some(())
}

fn encode_aot_match_kind(encoder: &mut AggregateAotBindingEncoder, match_kind: RustMatchKind) {
    match match_kind {
        RustMatchKind::LeftmostFirst => encoder.u8(0),
    }
}

#[allow(
    clippy::too_many_arguments,
    clippy::fn_params_excessive_bools,
    reason = "the fields exactly mirror one authenticated Rust constructor identity variant"
)]
fn encode_aot_rust_constructor_common(
    encoder: &mut AggregateAotBindingEncoder,
    size_limit: u64,
    dfa_size_limit: u64,
    text_syntax_utf8: bool,
    bytes_syntax_utf8: bool,
    text_utf8_empty: bool,
    bytes_utf8_empty: bool,
    match_kind: RustMatchKind,
) {
    encoder.u64(size_limit);
    encoder.u64(dfa_size_limit);
    encoder.boolean(text_syntax_utf8);
    encoder.boolean(bytes_syntax_utf8);
    encoder.boolean(text_utf8_empty);
    encoder.boolean(bytes_utf8_empty);
    encode_aot_match_kind(encoder, match_kind);
}

fn encode_aot_rust_constructor(
    encoder: &mut AggregateAotBindingEncoder,
    constructor: &RustConstructor,
) -> Option<()> {
    match constructor {
        RustConstructor::RegexBuilder {
            size_limit,
            dfa_size_limit,
            text_syntax_utf8,
            bytes_syntax_utf8,
            text_utf8_empty,
            bytes_utf8_empty,
            match_kind,
        } => {
            encoder.u8(0);
            encode_aot_rust_constructor_common(
                encoder,
                *size_limit,
                *dfa_size_limit,
                *text_syntax_utf8,
                *bytes_syntax_utf8,
                *text_utf8_empty,
                *bytes_utf8_empty,
                *match_kind,
            );
            Some(())
        }
        RustConstructor::RegexSetBuilder {
            size_limit,
            dfa_size_limit,
            text_syntax_utf8,
            bytes_syntax_utf8,
            text_utf8_empty,
            bytes_utf8_empty,
            match_kind,
        } => {
            encoder.u8(1);
            encode_aot_rust_constructor_common(
                encoder,
                *size_limit,
                *dfa_size_limit,
                *text_syntax_utf8,
                *bytes_syntax_utf8,
                *text_utf8_empty,
                *bytes_utf8_empty,
                *match_kind,
            );
            Some(())
        }
        RustConstructor::RebarMeta {
            rebar_revision,
            regex_default_features,
            regex_logging,
            regex_perf_dfa_full,
            regex_automata_default_features,
            syntax_utf8,
            utf8_empty,
            match_kind,
            build_many_ordered,
            thompson_nfa_size_limit,
            admission_status,
        } => {
            encoder.u8(2);
            encode_aot_upstream_revision(encoder, *rebar_revision)?;
            encoder.boolean(*regex_default_features);
            encoder.boolean(*regex_logging);
            encoder.boolean(*regex_perf_dfa_full);
            encoder.boolean(*regex_automata_default_features);
            encoder.boolean(*syntax_utf8);
            encoder.boolean(*utf8_empty);
            encode_aot_match_kind(encoder, *match_kind);
            encoder.boolean(*build_many_ordered);
            encoder.u64(*thompson_nfa_size_limit);
            encoder.u8(match *admission_status {
                AdmissionStatus::UpstreamOraclePending => 0,
                AdmissionStatus::QuotaChecked => 1,
            });
            Some(())
        }
    }
}

fn encode_aot_rust_profile(
    encoder: &mut AggregateAotBindingEncoder,
    profile: &RustProfile,
) -> Option<()> {
    encode_aot_package_identity(encoder, profile.regex)?;
    encode_aot_package_identity(encoder, profile.regex_automata)?;
    encode_aot_package_identity(encoder, profile.regex_syntax)?;
    encode_aot_unicode_version(encoder, profile.unicode);
    encode_aot_unicode_features(encoder, profile.unicode_features)?;
    encode_aot_rust_constructor(encoder, &profile.constructor)?;
    encoder.boolean(profile.options.case_insensitive);
    encoder.boolean(profile.options.multi_line);
    encoder.boolean(profile.options.dot_matches_new_line);
    encoder.boolean(profile.options.crlf);
    encoder.u8(profile.options.line_terminator);
    encoder.boolean(profile.options.swap_greed);
    encoder.boolean(profile.options.ignore_whitespace);
    encoder.boolean(profile.options.unicode);
    encoder.boolean(profile.options.octal);
    encoder.u32(profile.options.nest_limit);
    Some(())
}

fn encode_aot_aggregate_operation(
    encoder: &mut AggregateAotBindingEncoder,
    operation: AggregateOperation,
) {
    encoder.u8(match operation {
        AggregateOperation::Compile => 0,
        AggregateOperation::Spans => 1,
        AggregateOperation::Count => 2,
        AggregateOperation::SpanSum => 3,
    });
}

fn encode_aot_plan_selection(
    encoder: &mut AggregateAotBindingEncoder,
    selection: AggregatePlanSelection,
) {
    encoder.u8(match selection {
        AggregatePlanSelection::Auto => 0,
        AggregatePlanSelection::ForceExactLiteral => 1,
        AggregatePlanSelection::ForceContinuation => 2,
    });
}

fn encode_aot_exact_literal_identity(
    encoder: &mut AggregateAotBindingEncoder,
    identity: AggregateExactLiteralIdentity,
) -> Option<()> {
    encoder.u8(match identity.semantics {
        AggregateExactLiteralSemantics::UnicodeOffByteBoundaries => 0,
        AggregateExactLiteralSemantics::UnicodeOnNonemptyUtf8Literal => 1,
    });
    encoder.string(identity.kernel.plan_id)?;
    encoder.string(identity.kernel.operation_id)?;
    encoder.u8(match identity.kernel.operation {
        LiteralAggregateOperation::Count => 0,
        LiteralAggregateOperation::SpanSum => 1,
    });
    encoder.u8(match identity.kernel.boundary_semantics {
        LiteralAggregateBoundarySemantics::EveryByteBoundaryUnicodeOff => 0,
    });
    encoder.boolean(identity.kernel.non_overlapping);
    encoder.u32(identity.kernel.algorithm_version);
    encoder.u32(identity.kernel.accounting_version);
    encoder.u8(match identity.kernel.declared_fallback {
        LiteralAggregateDeclaredFallback::None => 0,
    });
    Some(())
}

fn encode_aot_exact_literal_build(
    encoder: &mut AggregateAotBindingEncoder,
    build: LiteralAggregateBuildAccounting,
) -> Option<()> {
    encoder.usize(build.needle_bytes)?;
    encoder.usize(build.temporary_capacity_bytes)?;
    encoder.u64(build.work_upper_bound);
    encoder.usize(build.scratch_bytes)?;
    encoder.usize(build.persistent_bytes)?;
    encoder.usize(build.peak_bytes)
}

fn aggregate_count_exact_literal_aot_semantic_binding_identity(
    report: &AggregateBuildReport,
    literal: &[u8],
    profile: &RustProfile,
    plan_identity: AggregateExactLiteralIdentity,
    build: LiteralAggregateBuildAccounting,
) -> Option<(AggregateCountExactLiteralAotSemanticBindingIdentity, u64)> {
    if report.operation != AggregateOperation::Count
        || report.plan != AggregatePlanKind::ExactLiteral
        || report.plan_identity != AggregatePlanIdentity::ExactLiteral(plan_identity)
        || report.build != AggregateBuildAccounting::ExactLiteral(build)
        || build.needle_bytes != literal.len()
        || !matches!(
            &report.syntax_key.profile,
            CompatibilityProfile::RustBytes(retained) if retained == profile
        )
    {
        return None;
    }

    let mut encoder = AggregateAotBindingEncoder::new();
    encoder.raw(b"fre.aggregate.count-exact-literal-aot-semantic-binding.v1\0");
    encoder.u32(AGGREGATE_COUNT_EXACT_LITERAL_AOT_SEMANTIC_BINDING_SCHEMA_VERSION);
    encoder.u32(report.schema_version);
    encoder.u32(report.syntax_key.schema_version);
    encoder.bytes(report.syntax_key.pattern.as_bytes())?;
    encoder.bytes(literal)?;
    encoder.u8(0); // CompatibilityProfile::RustBytes.
    encode_aot_rust_profile(&mut encoder, profile)?;
    encode_aot_aggregate_operation(&mut encoder, report.operation);
    encode_aot_plan_selection(&mut encoder, report.selection);
    encoder.u8(0); // AggregatePlanKind::ExactLiteral.
    encode_aot_exact_literal_identity(&mut encoder, plan_identity)?;
    encode_aot_exact_literal_build(&mut encoder, build)?;
    let (digest, bytes_hashed) = encoder.finish()?;
    Some((
        AggregateCountExactLiteralAotSemanticBindingIdentity(digest),
        bytes_hashed,
    ))
}

fn encode_aot_planning_parse_prospective(
    encoder: &mut AggregateAotPlanningEncoder,
    prospective: ParseAttemptProspective,
) -> Option<()> {
    encoder.u64(prospective.source_bytes)?;
    encoder.u64(prospective.max_observed_work)?;
    encoder.u64(prospective.max_hir_nodes)?;
    encoder.u64(prospective.max_nesting)?;
    encoder.u64(prospective.max_traversal_stack_items)?;
    encoder.u8(prospective.max_source_admission_checks)?;
    encoder.u8(prospective.max_configuration_checks)?;
    encoder.u8(prospective.max_opaque_parser_invocations)
}

fn encode_aot_planning_parse_actual(
    encoder: &mut AggregateAotPlanningEncoder,
    actual: ParseAttemptActual,
) -> Option<()> {
    encoder.u8(actual.source_admission_checks)?;
    encoder.u8(actual.configuration_checks)?;
    encoder.u8(actual.opaque_parser_invocations)?;
    encoder.u64(actual.availability_work)?;
    encoder.u64(actual.hir_summary_work)?;
    encoder.u64(actual.observed_work)?;
    encoder.u64(actual.hir_nodes)?;
    encoder.u64(actual.literal_bytes)?;
    encoder.u64(actual.class_ranges)?;
    encoder.u64(actual.captures)?;
    encoder.u64(actual.repetitions)?;
    encoder.u64(actual.max_depth)?;
    encoder.u64(actual.traversal_stack_peak)
}

fn encode_aot_planning_construction_prospective(
    encoder: &mut AggregateAotPlanningEncoder,
    prospective: AggregateConstructionProspective,
) -> Option<()> {
    encoder.u64(prospective.work)?;
    encoder.usize(prospective.allocations)?;
    encoder.usize(prospective.allocated_bytes)?;
    encoder.usize(prospective.copied_bytes)?;
    encoder.usize(prospective.initialized_bytes)?;
    encoder.u64(prospective.abandoned_work)?;
    encoder.usize(prospective.abandoned_allocations)?;
    encoder.usize(prospective.abandoned_bytes)?;
    encoder.usize(prospective.live_persistent_bytes)?;
    encoder.usize(prospective.high_water_bytes)
}

fn encode_aot_planning_construction_actual(
    encoder: &mut AggregateAotPlanningEncoder,
    actual: AggregateConstructionActual,
) -> Option<()> {
    encoder.u64(actual.work)?;
    encoder.usize(actual.allocations)?;
    encoder.usize(actual.allocated_bytes)?;
    encoder.usize(actual.copied_bytes)?;
    encoder.usize(actual.initialized_bytes)?;
    encoder.u64(actual.abandoned_work)?;
    encoder.usize(actual.abandoned_allocations)?;
    encoder.usize(actual.abandoned_bytes)?;
    encoder.usize(actual.live_persistent_bytes)?;
    encoder.usize(actual.high_water_bytes)
}

fn encode_aot_planning_effect(
    encoder: &mut AggregateAotPlanningEncoder,
    effect: AggregateConstructionEffect,
) -> Option<()> {
    encoder.u64(effect.work)?;
    encoder.usize(effect.allocations)?;
    encoder.usize(effect.allocated_bytes)?;
    encoder.usize(effect.copied_bytes)?;
    encoder.usize(effect.initialized_bytes)?;
    encoder.usize(effect.retained_persistent_bytes)?;
    encoder.usize(effect.released_persistent_bytes)?;
    encoder.usize(effect.co_live_bytes)
}

fn encode_aot_planning_abandonment(
    encoder: &mut AggregateAotPlanningEncoder,
    abandonment: AggregateConstructionAbandonment,
) -> Option<()> {
    encoder.u64(abandonment.work)?;
    encoder.usize(abandonment.allocations)?;
    encoder.usize(abandonment.bytes)?;
    encoder.usize(abandonment.released_persistent_bytes)
}

fn encode_aot_planning_fallback(
    encoder: &mut AggregateAotPlanningEncoder,
    fallback: AggregateConstructionPrepublicationFallback,
) -> Option<()> {
    encoder.u8(match fallback {
        AggregateConstructionPrepublicationFallback::None => 0,
        AggregateConstructionPrepublicationFallback::FixedAbsoluteOptionalInspectionResource => 1,
        AggregateConstructionPrepublicationFallback::FixedAbsoluteOptionalResidualResource => 2,
        AggregateConstructionPrepublicationFallback::FixedAbsoluteOptionalGuardResource => 3,
        AggregateConstructionPrepublicationFallback::FixedAbsoluteOptionalBuildResource => 4,
        AggregateConstructionPrepublicationFallback::SparseFiniteMaterializationScratch => 5,
        AggregateConstructionPrepublicationFallback::SparseFiniteMaterializationPeak => 6,
        AggregateConstructionPrepublicationFallback::SparseFiniteBuildResource => 7,
        AggregateConstructionPrepublicationFallback::GuardedFiniteDictionaryResource => 8,
        AggregateConstructionPrepublicationFallback::GuardedFiniteConstructionResource => 9,
        AggregateConstructionPrepublicationFallback::DenseFiniteBuildResourceToFixedPredicateWord64 => 10,
        AggregateConstructionPrepublicationFallback::DenseFiniteBuildResourceToContinuation => 11,
        AggregateConstructionPrepublicationFallback::TooLargeFixedSequenceToFixedPredicateWord64 => 12,
        AggregateConstructionPrepublicationFallback::FixedPredicateWord64BuildResource => 13,
        AggregateConstructionPrepublicationFallback::PackedFiniteBuildResourceToDenseFinite => 14,
    })
}

fn encode_aot_planning_transition(
    encoder: &mut AggregateAotPlanningEncoder,
    transition: AggregateConstructionTransition,
) -> Option<()> {
    match transition {
        AggregateConstructionTransition::Advance(stage) => {
            encoder.u8(0)?;
            encoder.usize(stage.ordinal())
        }
        AggregateConstructionTransition::Selected => encoder.u8(1),
        AggregateConstructionTransition::FixedAbsoluteToSparseFiniteRoot => encoder.u8(2),
        AggregateConstructionTransition::SparseFiniteToContinuation => encoder.u8(3),
        AggregateConstructionTransition::GuardedFiniteToContinuation => encoder.u8(4),
        AggregateConstructionTransition::DenseFiniteToFixedPredicateWord64 => encoder.u8(5),
        AggregateConstructionTransition::DenseFiniteToContinuation => encoder.u8(6),
        AggregateConstructionTransition::TooLargeFixedSequenceToFixedPredicateWord64 => {
            encoder.u8(7)
        }
        AggregateConstructionTransition::FixedPredicateWord64ToContinuation => encoder.u8(8),
        AggregateConstructionTransition::HardTerminal => encoder.u8(9),
        AggregateConstructionTransition::Published => encoder.u8(10),
        AggregateConstructionTransition::PackedFiniteToDenseFinite => encoder.u8(11),
    }
}

fn encode_aot_planning_ledger_entry(
    encoder: &mut AggregateAotPlanningEncoder,
    entry: &crate::AggregateConstructionLedgerEntry,
) -> Option<()> {
    encoder.usize(entry.stage.ordinal())?;
    encoder.u8(match entry.disposition {
        AggregateConstructionStageDisposition::PolicySkipped => 0,
        AggregateConstructionStageDisposition::SemanticIneligible => 1,
        AggregateConstructionStageDisposition::Completed => 2,
        AggregateConstructionStageDisposition::Selected => 3,
        AggregateConstructionStageDisposition::SoftResourceRefused => 4,
        AggregateConstructionStageDisposition::HardTerminal => 5,
        AggregateConstructionStageDisposition::Published => 6,
    })?;
    encode_aot_planning_fallback(encoder, entry.fallback)?;
    encode_aot_planning_transition(encoder, entry.transition)?;
    encode_aot_planning_effect(encoder, entry.effect)?;
    encode_aot_planning_abandonment(encoder, entry.abandonment)?;
    encode_aot_planning_construction_actual(encoder, entry.actual)
}

fn aggregate_aot_report_planner_work(report: &AggregateBuildReport) -> Option<u64> {
    let mut total = 0_u64;
    for work in [
        report.planner_work,
        report.unicode_scalar_planner_work,
        report.word_run_planner_work,
        report.literal_assertions_planner_work,
        report.blocking_delimiter_planner_work,
        report.token_phrase_planner_work,
        report.fixed_class_sandwich_planner_work,
        report.bounded_affix_planner_work,
        report.grapheme_scalar_dfa_planner_work,
        report.bounded_class_sequence_planner_work,
        report.bounded_separated_fields_planner_work,
        report.prefix_class_alternation_planner_work,
        report.literal_class_run_literal_planner_work,
        report.bounded_literal_pair_planner_work,
        report.bounded_context_planner_work,
        usize::try_from(report.fixed_absolute_planner_work).ok()?,
        report.capture_erasure_work,
    ] {
        total = total.checked_add(u64::try_from(work).ok()?)?;
    }
    total.checked_add(report.finite_planner_work)
}

fn encode_aot_planning_report(
    encoder: &mut AggregateAotPlanningEncoder,
    report: &AggregateBuildReport,
) -> Option<()> {
    encoder.u32(report.schema_version)?;
    encoder.u32(report.syntax_key.schema_version)?;
    encoder.u8(match report.admission {
        AdmissionStatus::UpstreamOraclePending => 0,
        AdmissionStatus::QuotaChecked => 1,
    })?;
    encoder.u8(2)?; // AggregateOperation::Count.
    encoder.u8(1)?; // AggregatePlanSelection::ForceExactLiteral.
    encoder.u8(1)?; // AggregateStrategy::ReverseSequentialRows.
    encoder.u8(0)?; // AggregatePlanKind::ExactLiteral.
    encoder.u8(0)?; // continuation_strategy: None.
    encoder.u8(0)?; // AggregateCaptureSemantics::ErasedForWholeMatchOnly.

    let syntax = &report.syntax;
    encoder.u64(syntax.hir_nodes)?;
    encoder.u64(syntax.max_depth)?;
    encoder.u64(syntax.parse_work)?;
    encoder.u64(syntax.literal_bytes)?;
    encoder.u64(syntax.class_ranges)?;
    encoder.u64(syntax.captures)?;
    encoder.u64(syntax.repetitions)?;
    match syntax.largest_finite_repeat {
        Some(repeat) => {
            encoder.u8(1)?;
            encoder.u32(repeat)?;
        }
        None => encoder.u8(0)?,
    }
    encoder.boolean(syntax.guarantees_valid_utf8_nonempty)?;

    for work in [
        report.planner_work,
        report.unicode_scalar_planner_work,
        report.word_run_planner_work,
        report.literal_assertions_planner_work,
        report.blocking_delimiter_planner_work,
        report.token_phrase_planner_work,
        report.fixed_class_sandwich_planner_work,
        report.bounded_affix_planner_work,
        report.grapheme_scalar_dfa_planner_work,
        report.bounded_class_sequence_planner_work,
        report.bounded_separated_fields_planner_work,
        report.prefix_class_alternation_planner_work,
        report.literal_class_run_literal_planner_work,
        report.bounded_literal_pair_planner_work,
        report.bounded_context_planner_work,
        usize::try_from(report.fixed_absolute_planner_work).ok()?,
        report.capture_erasure_work,
        report.captures_erased,
    ] {
        encoder.usize(work)?;
    }
    encoder.u64(report.finite_planner_work)?;
    encoder.usize(report.retained_capacity_bytes)
}

fn encode_aot_planning_effective_policy(
    encoder: &mut AggregateAotPlanningEncoder,
    limits: &AggregateBuildLimits,
) -> Option<()> {
    if !matches_aot_count_exact_literal_v1_policy(limits) {
        return None;
    }
    let AdmissionPolicy::Quota(quota) = limits.admission else {
        return None;
    };
    encoder.u8(1)?; // Quota admission.
    encoder.u64(quota.syntax.max_pattern_bytes)?;
    encoder.u64(quota.syntax.max_nesting)?;
    encoder.u64(quota.syntax.max_hir_nodes)?;
    encoder.u64(quota.syntax.max_parse_work)?;
    encoder.u64(quota.syntax.max_traversal_stack)?;
    encoder.u64(limits.syntax_safety.max_pattern_bytes)?;
    encoder.u64(limits.syntax_safety.max_nesting)?;
    encoder.u64(limits.syntax_safety.max_hir_nodes)?;
    encoder.u64(limits.syntax_safety.max_parse_work)?;
    encoder.u64(limits.syntax_safety.max_traversal_stack)?;
    encoder.usize(limits.max_literal_planner_work)?;
    encoder.usize(limits.exact_literal.max_needle_bytes)?;
    encoder.u64(limits.exact_literal.max_build_work)?;
    encoder.usize(limits.exact_literal.max_scratch_bytes)?;
    encoder.usize(limits.exact_literal.max_persistent_bytes)?;
    encoder.usize(limits.exact_literal.max_peak_bytes)
}

fn aggregate_count_exact_literal_aot_planning_receipt(
    report: &AggregateBuildReport,
    semantic_binding_identity: AggregateCountExactLiteralAotSemanticBindingIdentity,
    plan_identity: AggregateExactLiteralIdentity,
    build: LiteralAggregateBuildAccounting,
    construction: &AggregateConstructionReceipt,
    syntax: &fre_syntax::ParseAttemptReceipt,
) -> Option<(
    AggregateCountExactLiteralAotPlanningReceiptIdentity,
    AggregateCountExactLiteralAotPlanningAccounting,
)> {
    if report.operation != AggregateOperation::Count
        || report.selection != AggregatePlanSelection::ForceExactLiteral
        || report.requested_strategy != AggregateStrategy::ReverseSequentialRows
        || !matches_aot_count_exact_literal_v1_policy(&report.build_limits)
        || report.plan != AggregatePlanKind::ExactLiteral
        || report.continuation_strategy.is_some()
        || report.capture_semantics != AggregateCaptureSemantics::ErasedForWholeMatchOnly
        || report.plan_identity != AggregatePlanIdentity::ExactLiteral(plan_identity)
        || report.build != AggregateBuildAccounting::ExactLiteral(build)
    {
        return None;
    }
    let construction_prospective = construction.prospective?;
    let syntax_prospective = syntax.prospective?;
    let request = construction.identity.request_owner.request();
    let published = construction.published_plan.as_ref()?;
    if construction.identity.declared_fallback_policy
        != AggregateConstructionDeclaredFallbackPolicy::CurrentSelectorOrder
        || construction.terminal != AggregateConstructionTerminal::Success
        || construction.published_stage != Some(AggregateConstructionStage::ExactLiteral)
        || published.stage() != AggregateConstructionStage::ExactLiteral
        || published.plan() != &AggregatePlanIdentity::ExactLiteral(plan_identity)
        || syntax.terminal != ParseAttemptTerminal::Success
        || !syntax.authenticates_canonical()
        || !syntax.identity.has_stable_source_owner()
        || request.syntax_request != syntax.identity
    {
        return None;
    }
    let ledger_entries = u8::try_from(construction.ledger.len()).ok()?;
    let report_planner_work = aggregate_aot_report_planner_work(report)?;
    if construction_prospective.work
        > AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_WORK_UPPER_BOUND_V1
        || construction.actual.work > construction_prospective.work
    {
        return None;
    }

    let mut encoder = AggregateAotPlanningEncoder::new();
    encoder.raw(b"fre.aggregate.count-exact-literal-aot-planning-receipt.v1\0")?;
    encoder.u32(AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_RECEIPT_SCHEMA_VERSION)?;
    encoder.u32(AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_POLICY_VERSION)?;
    encoder.u64(AGGREGATE_COUNT_EXACT_LITERAL_AOT_PLANNING_WORK_UPPER_BOUND_V1)?;
    encoder.u64(AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1)?;
    encoder.raw(semantic_binding_identity.as_bytes())?;
    encode_aot_planning_effective_policy(&mut encoder, &report.build_limits)?;
    encode_aot_planning_report(&mut encoder, report)?;
    encode_aot_exact_literal_identity_for_planning(&mut encoder, plan_identity)?;
    encode_aot_exact_literal_build_for_planning(&mut encoder, build)?;

    encoder.u32(construction.identity.explain_schema_version)?;
    encoder.u32(construction.identity.algorithm_version)?;
    encoder.u32(construction.identity.accounting_version)?;
    encoder.u8(0)?; // CurrentSelectorOrder.
    encoder.u32(syntax.identity.schema_version)?;
    encoder.u64(syntax.identity.source_bytes)?;
    encoder.usize(syntax.identity.source_capacity_bytes())?;
    encoder.boolean(syntax.identity.has_bound_source_origin())?;
    encoder.boolean(syntax.identity.has_stable_source_owner())?;
    encoder.u32(syntax.identity.algorithm_version)?;
    encoder.u32(syntax.identity.accounting_version)?;
    encoder.u8(0)?; // ParseAttemptDeclaredFallback::None.
    encode_aot_planning_parse_prospective(&mut encoder, syntax_prospective)?;
    encode_aot_planning_parse_actual(&mut encoder, syntax.actual)?;
    encoder.u8(0)?; // ParseAttemptTerminal::Success.

    encode_aot_planning_construction_prospective(&mut encoder, construction_prospective)?;
    encode_aot_planning_construction_actual(&mut encoder, construction.actual)?;
    encoder.u8(ledger_entries)?;
    for entry in construction.ledger.iter() {
        encode_aot_planning_ledger_entry(&mut encoder, entry)?;
    }
    encoder.usize(AggregateConstructionStage::ExactLiteral.ordinal())?;
    encoder.u8(0)?; // AggregateConstructionTerminal::Success.
    let (digest, identity_bytes_hashed) = encoder.finish();

    Some((
        AggregateCountExactLiteralAotPlanningReceiptIdentity(digest),
        AggregateCountExactLiteralAotPlanningAccounting {
            source_bytes: syntax.identity.source_bytes,
            source_capacity_bytes: syntax.identity.source_capacity_bytes(),
            syntax_prospective,
            syntax_actual: syntax.actual,
            construction_prospective,
            construction_actual: construction.actual,
            construction_ledger_entries: ledger_entries,
            report_planner_work,
            report_retained_capacity_bytes: report.retained_capacity_bytes,
            identity_bytes_hashed,
        },
    ))
}

fn aggregate_count_exact_literal_aot_projection_accounting(
    semantic_identity_bytes_hashed: u64,
    planning: &AggregateCountExactLiteralAotPlanningAccounting,
) -> Option<AggregateCountExactLiteralAotIdentityProjectionAccounting> {
    let planning_identity_bytes_hashed = planning.identity_bytes_hashed();
    let canonical_bytes =
        semantic_identity_bytes_hashed.checked_add(planning_identity_bytes_hashed)?;
    // One unit to encode and one unit to feed each canonical byte, plus a
    // fixed comparison/closure allowance and one fixed allowance per typed
    // ledger entry. Both SHA projections are sequential, so only one hasher
    // state is co-live.
    let fixed_work = 1_024_u64
        .checked_add(u64::from(planning.construction_ledger_entries()).checked_mul(256)?)?;
    let computed_projection_work_upper_bound =
        canonical_bytes.checked_mul(2)?.checked_add(fixed_work)?;
    let accounting = AggregateCountExactLiteralAotIdentityProjectionAccounting {
        semantic_identity_bytes_hashed,
        planning_identity_bytes_hashed,
        // Construction charges this fixed ceiling before publication. The
        // receipt can therefore include its own final work counter without a
        // self-referential variable charge.
        projection_work_upper_bound:
            AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1,
        scratch_bytes_upper_bound: u64::try_from(core::mem::size_of::<Sha256>()).ok()?,
        allocations: 0,
    };
    (computed_projection_work_upper_bound
        <= AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1)
        .then_some(accounting)
}

fn aggregate_count_exact_literal_aot_semantic_projection_accounting(
    semantic_identity_bytes_hashed: u64,
) -> Option<AggregateCountExactLiteralAotIdentityProjectionAccounting> {
    let computed_projection_work_upper_bound = semantic_identity_bytes_hashed
        .checked_mul(2)?
        .checked_add(1_024)?;
    (computed_projection_work_upper_bound
        <= AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1)
        .then_some(AggregateCountExactLiteralAotIdentityProjectionAccounting {
            semantic_identity_bytes_hashed,
            planning_identity_bytes_hashed: 0,
            projection_work_upper_bound:
                AGGREGATE_COUNT_EXACT_LITERAL_AOT_CANDIDATE_IDENTITY_WORK_UPPER_BOUND_V1,
            scratch_bytes_upper_bound: u64::try_from(core::mem::size_of::<Sha256>()).ok()?,
            allocations: 0,
        })
}

fn aggregate_count_exact_literal_aot_cached_projection(
    report: &AggregateBuildReport,
    engine: &AggregateExactLiteralEngine,
    construction: &AggregateConstructionReceipt,
    syntax: &fre_syntax::ParseAttemptReceipt,
) -> Option<AggregateCountExactLiteralAotCachedProjection> {
    if report.operation != AggregateOperation::Count {
        return None;
    }
    let AggregatePlanIdentity::ExactLiteral(plan_identity) = report.plan_identity else {
        return None;
    };
    let AggregateBuildAccounting::ExactLiteral(build_accounting) = report.build else {
        return None;
    };
    let CompatibilityProfile::RustBytes(profile) = &report.syntax_key.profile else {
        return None;
    };
    if build_accounting != engine.build_accounting()
        || build_accounting.needle_bytes != engine.needle().len()
    {
        return None;
    }
    let (semantic_binding_identity, semantic_identity_bytes_hashed) =
        aggregate_count_exact_literal_aot_semantic_binding_identity(
            report,
            engine.needle(),
            profile,
            plan_identity,
            build_accounting,
        )?;
    let semantic_projection_accounting =
        aggregate_count_exact_literal_aot_semantic_projection_accounting(
            semantic_identity_bytes_hashed,
        )?;
    let planning = aggregate_count_exact_literal_aot_planning_receipt(
        report,
        semantic_binding_identity,
        plan_identity,
        build_accounting,
        construction,
        syntax,
    )
    .and_then(|(identity, accounting)| {
        aggregate_count_exact_literal_aot_projection_accounting(
            semantic_identity_bytes_hashed,
            &accounting,
        )
        .map(|projection| (identity, accounting, projection))
    });
    Some(AggregateCountExactLiteralAotCachedProjection {
        semantic_binding_identity,
        semantic_projection_accounting,
        planning,
    })
}

fn encode_aot_exact_literal_identity_for_planning(
    encoder: &mut AggregateAotPlanningEncoder,
    identity: AggregateExactLiteralIdentity,
) -> Option<()> {
    encoder.u8(match identity.semantics {
        AggregateExactLiteralSemantics::UnicodeOffByteBoundaries => 0,
        AggregateExactLiteralSemantics::UnicodeOnNonemptyUtf8Literal => 1,
    })?;
    encoder.bytes(identity.kernel.plan_id.as_bytes())?;
    encoder.bytes(identity.kernel.operation_id.as_bytes())?;
    encoder.u8(match identity.kernel.operation {
        LiteralAggregateOperation::Count => 0,
        LiteralAggregateOperation::SpanSum => 1,
    })?;
    encoder.u8(match identity.kernel.boundary_semantics {
        LiteralAggregateBoundarySemantics::EveryByteBoundaryUnicodeOff => 0,
    })?;
    encoder.boolean(identity.kernel.non_overlapping)?;
    encoder.u32(identity.kernel.algorithm_version)?;
    encoder.u32(identity.kernel.accounting_version)?;
    encoder.u8(match identity.kernel.declared_fallback {
        LiteralAggregateDeclaredFallback::None => 0,
    })
}

fn encode_aot_exact_literal_build_for_planning(
    encoder: &mut AggregateAotPlanningEncoder,
    build: LiteralAggregateBuildAccounting,
) -> Option<()> {
    encoder.usize(build.needle_bytes)?;
    encoder.usize(build.temporary_capacity_bytes)?;
    encoder.u64(build.work_upper_bound)?;
    encoder.usize(build.scratch_bytes)?;
    encoder.usize(build.persistent_bytes)?;
    encoder.usize(build.peak_bytes)
}

/// Lossless receipt-local source storage.
///
/// The public guarded-word source is boxed to keep the outer execution error
/// compact. Keeping its receipt copy unboxed avoids a second allocation while
/// every other direct source can retain its existing representation exactly.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct AggregateExactLiteralConstructionSeal {
    encoded_needle_bytes: usize,
    temporary_capacity_bytes: usize,
    origin: LiteralAggregatePlanOrigin,
}

impl AggregateExactLiteralConstructionSeal {
    fn new(
        build: LiteralAggregateBuildAccounting,
        identity: LiteralAggregateOperationIdentity,
        origin: LiteralAggregatePlanOrigin,
    ) -> Option<Self> {
        let dispatched = identity
            == LiteralAggregateOperationIdentity::for_dispatched_operation(identity.operation);
        if !dispatched
            && identity != LiteralAggregateOperationIdentity::for_operation(identity.operation)
        {
            return None;
        }
        let seal = Self {
            encoded_needle_bytes: build
                .needle_bytes
                .checked_mul(2)?
                .checked_add(usize::from(dispatched))?,
            temporary_capacity_bytes: build.temporary_capacity_bytes,
            origin,
        };
        (seal.build_accounting()? == build).then_some(seal)
    }

    fn build_accounting(self) -> Option<LiteralAggregateBuildAccounting> {
        let needle_bytes = self.encoded_needle_bytes / 2;
        let dispatched = self.encoded_needle_bytes & 1 != 0;
        if needle_bytes == 0 && self.temporary_capacity_bytes != 0 {
            return None;
        }
        let established_work = u64::try_from(needle_bytes).ok()?.checked_add(1)?;
        let (work_upper_bound, owner_bytes) = if dispatched && needle_bytes == 1 {
            (
                established_work
                    .checked_add(DispatchedLiteralAggregatePlan::classifier_build_work())?,
                core::mem::size_of::<DispatchedLiteralAggregatePlan>().checked_add(
                    // The public dispatched handle is stack-neutral; its
                    // established proof and classifier live in one exact
                    // retained allocation.
                    DispatchedLiteralAggregatePlan::retained_owner_bytes(),
                )?,
            )
        } else if !dispatched {
            (
                established_work,
                core::mem::size_of::<LiteralAggregatePlan>(),
            )
        } else {
            return None;
        };
        let persistent_bytes = owner_bytes.checked_add(needle_bytes)?;
        let peak_bytes = persistent_bytes.checked_add(self.temporary_capacity_bytes)?;
        Some(LiteralAggregateBuildAccounting {
            needle_bytes,
            temporary_capacity_bytes: self.temporary_capacity_bytes,
            work_upper_bound,
            scratch_bytes: self.temporary_capacity_bytes,
            persistent_bytes,
            peak_bytes,
        })
    }

    const fn is_dispatched(self) -> bool {
        self.encoded_needle_bytes & 1 != 0
    }
}

#[derive(Clone, Debug)]
struct AggregateExactLiteralReceiptSource {
    attempt: LiteralAggregateReduceAttemptError,
    syntax_provenance: Weak<CacheKey>,
    construction: AggregateExactLiteralConstructionSeal,
}

impl PartialEq for AggregateExactLiteralReceiptSource {
    fn eq(&self, other: &Self) -> bool {
        self.attempt == other.attempt
            && Weak::ptr_eq(&self.syntax_provenance, &other.syntax_provenance)
            && self.construction == other.construction
    }
}

impl Eq for AggregateExactLiteralReceiptSource {}

#[derive(Clone, Debug, Eq, PartialEq)]
#[allow(
    clippy::large_enum_variant,
    reason = "exact terminals retain one inline receipt and construction seal; boxing would add a forbidden second allocation"
)]
enum AggregateDirectReceiptSource {
    Execution(AggregateExecutionSource),
    ExactLiteral(AggregateExactLiteralReceiptSource),
    GuardedAsciiWord(guarded_ascii_word::ReduceError),
}

impl AggregateDirectReceiptSource {
    fn capture(source: &AggregateExecutionSource) -> Option<Self> {
        match source {
            AggregateExecutionSource::ExactLiteral(_) => None,
            AggregateExecutionSource::GuardedAsciiWord(source) => {
                Some(Self::GuardedAsciiWord(source.as_ref().clone()))
            }
            source => Some(Self::Execution(source.clone())),
        }
    }

    fn authenticates(&self, source: &AggregateExecutionSource) -> bool {
        match (self, source) {
            (Self::Execution(receipt), source) => receipt == source,
            (
                Self::ExactLiteral(AggregateExactLiteralReceiptSource { attempt, .. }),
                AggregateExecutionSource::ExactLiteral(source),
            ) => attempt.source() == source,
            (
                Self::GuardedAsciiWord(receipt),
                AggregateExecutionSource::GuardedAsciiWord(source),
            ) => receipt == source.as_ref(),
            (Self::ExactLiteral(_) | Self::GuardedAsciiWord(_), _) => false,
        }
    }

    const fn exact_literal_receipt(&self) -> Option<&LiteralAggregateReduceAttemptReceipt> {
        match self {
            Self::ExactLiteral(source) => Some(source.attempt.receipt()),
            Self::Execution(_) | Self::GuardedAsciiWord(_) => None,
        }
    }

    fn exact_literal_closes(
        &self,
        owner: &AggregateDirectOwnerSeal,
        cache: &AggregateCacheIdentity,
        invocation: &AggregateDirectInvocation,
    ) -> bool {
        let Self::ExactLiteral(source) = self else {
            return owner.identity.route != AggregateDirectRoute::ExactLiteral;
        };
        let receipt = source.attempt.receipt();
        let Some(construction_build) = source.construction.build_accounting() else {
            return false;
        };
        let AggregatePlanIdentity::ExactLiteral(identity) = cache.plan_identity else {
            return false;
        };
        let Some(operation) = exact_literal_operation(cache.operation) else {
            return false;
        };
        let prospective_closes = receipt.prospective.is_none_or(|prospective| {
            prospective.haystack_bytes == receipt.invocation.haystack_bytes
                && prospective.needle_bytes == receipt.invocation.build.needle_bytes
                && prospective.persistent_bytes == receipt.invocation.build.persistent_bytes
                && prospective.operation_allocations == 0
        });
        let expected_origin = LiteralAggregatePlanOrigin::from_external_address(
            owner.syntax_provenance.as_ptr().cast::<()>().addr(),
        );
        Weak::ptr_eq(&source.syntax_provenance, &owner.syntax_provenance)
            && owner.identity.route == AggregateDirectRoute::ExactLiteral
            && identity.kernel.authenticates_operation(operation)
            && source.construction.is_dispatched()
                == (identity.kernel
                    == LiteralAggregateOperationIdentity::for_dispatched_operation(operation))
            && expected_origin == Some(source.construction.origin)
            && receipt.authenticates(
                identity.kernel,
                LiteralAggregateReduceInvocation {
                    haystack_bytes: invocation.haystack_len,
                    build: construction_build,
                    plan_origin: source.construction.origin,
                    limits: cache.execution_limits.exact_literal,
                },
            )
            && receipt.invocation.haystack_bytes == invocation.haystack_len
            && receipt.invocation.limits == cache.execution_limits.exact_literal
            && prospective_closes
            && source.attempt.closes()
            && receipt.actual.operation_allocations == 0
            && receipt.actual_allocations == 0
            && receipt.retains_bounded_actual()
    }
}

/// Lossless terminal receipt for one construction-owned direct route.
///
/// Existing reducer errors are deliberately retained intact: limit refusals
/// preserve their exact prospective dimension, and post-publication
/// accounting failures preserve their typed upper/actual values. U0-E can add
/// the exact-literal kernel's finer-grained receipt without changing this
/// owner-local envelope.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateDirectAttemptReceipt {
    owner: AggregateDirectOwnerSeal,
    pub invocation: AggregateDirectInvocation,
    source: AggregateDirectReceiptSource,
    authenticated_terminal: AggregateDirectAttemptTerminal,
    pub terminal: AggregateDirectAttemptTerminal,
}

impl AggregateDirectAttemptReceipt {
    /// Construction owner shared by first, steady, and terminal attempts.
    #[must_use]
    pub const fn owner(&self) -> &AggregateDirectOwnerSeal {
        &self.owner
    }

    /// Exact invocation limits bound before the selected route executes.
    #[must_use]
    pub const fn run_limits(&self) -> AggregateRunLimits {
        self.owner.authenticated_execution_limits
    }

    /// Authenticate the complete typed reducer terminal retained by this
    /// receipt. Guarded-word terminals use an unboxed receipt copy so error
    /// packaging does not perform a second allocation.
    #[must_use]
    pub fn authenticates_source(&self, source: &AggregateExecutionSource) -> bool {
        self.source.authenticates(source)
    }

    /// Exact-literal kernel receipt nested under this construction owner.
    #[must_use]
    pub const fn exact_literal_receipt(&self) -> Option<&LiteralAggregateReduceAttemptReceipt> {
        self.source.exact_literal_receipt()
    }

    fn closes(&self, cache: &AggregateCacheIdentity, source: &AggregateExecutionSource) -> bool {
        self.authenticated_terminal == AggregateDirectAttemptTerminal::Failure
            && self.terminal == self.authenticated_terminal
            && self.authenticates_source(source)
            && self.run_limits() == cache.execution_limits
            && self.invocation.operation == cache.operation
            && self.invocation.range == (0..self.invocation.haystack_len)
            && source.direct_route() == Some(self.owner.identity.route)
            && self
                .source
                .exact_literal_closes(&self.owner, cache, &self.invocation)
            && self.owner.closes_cache_identity(cache)
    }
}

/// Exact construction owner, cache identity, and terminal receipt for a direct
/// aggregate execution failure.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateDirectAttemptIdentity {
    cache: AggregateCacheIdentity,
    receipt: AggregateDirectAttemptReceipt,
}

impl AggregateDirectAttemptIdentity {
    /// Complete structural cache identity used by this invocation.
    #[must_use]
    pub fn cache_identity(&self) -> &AggregateCacheIdentity {
        &self.cache
    }

    /// The one lossless construction-owned terminal receipt.
    #[must_use]
    pub const fn receipt(&self) -> &AggregateDirectAttemptReceipt {
        &self.receipt
    }
}

/// Allocation-free error identity for the U1 fixed-domain route. Only the
/// limits that authenticate its nested guard/continuation receipts are kept;
/// construction accounting lives once in the colocated owner seal.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AggregateFixedAbsoluteDomainErrorIdentity {
    pub schema_version: u32,
    pub syntax_key: Arc<CacheKey>,
    pub operation: AggregateOperation,
    pub selection: AggregatePlanSelection,
    pub continuation_strategy: Option<AggregateStrategy>,
    pub capture_semantics: AggregateCaptureSemantics,
    pub admission: AdmissionPolicy,
    pub syntax_safety: SafetyEnvelope,
    pub max_fixed_absolute_planner_work: usize,
    pub fixed_absolute_planner_work: usize,
    pub plan_identity: AggregateFixedAbsoluteDomainIdentity,
    pub guard_build_limits: FixedAbsoluteDomainBuildLimits,
    pub residual_build_limits: AggregateFixedAbsoluteDomainResidualBuildLimits,
    pub continuation_build_limits: AggregateCompileLimits,
    pub residual_allocation_census: Option<usize>,
}

fn fixed_guard_build_actual_fits(
    actual: FixedAbsoluteDomainBuildActual,
    prospective: FixedAbsoluteDomainBuildProspective,
) -> bool {
    actual.items <= prospective.items
        && actual.payload_bytes <= prospective.payload_bytes
        && actual.identity_bytes <= prospective.identity_bytes
        && actual.retained_heap_bytes <= prospective.retained_heap_bytes
        && actual.copied_bytes <= prospective.copied_bytes
        && actual.allocations <= prospective.allocations
        && actual.initialized_bytes <= prospective.initialized_bytes
        && actual.build_work <= prospective.build_work
        && actual.scratch_bytes <= prospective.scratch_bytes
        && actual.persistent_bytes <= prospective.persistent_bytes
        && actual.peak_bytes <= prospective.peak_bytes
        && actual.published
}

/// One-pointer construction owner for a successfully published fixed-domain
/// artifact. Equality is exact owner provenance, not structural Arc contents.
#[derive(Clone, Debug)]
pub struct AggregateExecutionIdentity(Arc<AggregateExecutionIdentityInner>);

#[derive(Debug)]
struct AggregateExecutionIdentityInner {
    seal: AggregateFixedAbsoluteDomainSeal,
    identity: AggregateFixedAbsoluteDomainErrorIdentity,
}

impl PartialEq for AggregateExecutionIdentity {
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.0, &other.0)
    }
}

impl Eq for AggregateExecutionIdentity {}

impl AggregateExecutionIdentity {
    fn fixed_absolute_domain(
        seal: AggregateFixedAbsoluteDomainSeal,
        identity: AggregateFixedAbsoluteDomainErrorIdentity,
    ) -> Self {
        Self(Arc::new(AggregateExecutionIdentityInner { seal, identity }))
    }

    #[must_use]
    pub fn as_fixed_absolute_domain(&self) -> &AggregateFixedAbsoluteDomainErrorIdentity {
        &self.0.identity
    }

    fn fixed_absolute_domain_seal(&self) -> &AggregateFixedAbsoluteDomainSeal {
        &self.0.seal
    }

    fn attach_construction_attempt(
        &mut self,
        receipt: AggregateConstructionReceipt,
    ) -> Result<(), &'static str> {
        let inner = Arc::get_mut(&mut self.0)
            .ok_or("fixed-domain construction owner was shared before publication")?;
        if inner.seal.construction_attempt.is_some() {
            return Err("fixed-domain construction receipt was already attached");
        }
        inner.seal.construction_attempt = Some(receipt);
        Ok(())
    }

    fn construction_attempt_receipt(&self) -> Option<&AggregateConstructionReceipt> {
        self.0.seal.construction_attempt.as_ref()
    }

    fn has_closed_fixed_construction(&self) -> bool {
        let sealed = &self.0.seal;
        let identity = &self.0.identity;
        sealed.has_closed_construction_attempt()
            && identity.schema_version == sealed.schema_version
            && identity.syntax_key == sealed.syntax_key
            && identity.operation == sealed.operation
            && identity.selection == sealed.selection
            && identity.continuation_strategy == sealed.continuation_strategy
            && identity.capture_semantics == sealed.capture_semantics
            && identity.admission == sealed.admission_policy
            && identity.syntax_safety == sealed.syntax_safety
            && identity.max_fixed_absolute_planner_work == sealed.max_fixed_absolute_planner_work
            && identity.fixed_absolute_planner_work == sealed.fixed_absolute_planner_work
            && identity.plan_identity == sealed.identity
            && identity.guard_build_limits == sealed.guard_build_limits
            && identity.residual_build_limits == sealed.residual_build_limits
            && identity.continuation_build_limits == sealed.continuation_build_limits
            && identity.residual_allocation_census == sealed.residual_allocation_census
    }
}

/// Opaque fixed-domain attempt identity. Construction provenance and its one
/// lossless terminal receipt cannot be separated or reassembled by callers.
#[derive(Clone, Debug)]
pub struct AggregateFixedAbsoluteDomainAttemptIdentity {
    owner: AggregateExecutionIdentity,
    receipt: AggregateFixedAbsoluteDomainAttemptReceipt,
}

impl PartialEq for AggregateFixedAbsoluteDomainAttemptIdentity {
    fn eq(&self, other: &Self) -> bool {
        self.owner == other.owner && self.receipt == other.receipt
    }
}

impl Eq for AggregateFixedAbsoluteDomainAttemptIdentity {}

impl AggregateFixedAbsoluteDomainAttemptIdentity {
    fn new(
        owner: AggregateExecutionIdentity,
        receipt: AggregateFixedAbsoluteDomainAttemptReceipt,
    ) -> Self {
        Self { owner, receipt }
    }

    /// Exact construction-owned fixed-route identity for this attempt.
    #[must_use]
    pub fn owner_identity(&self) -> &AggregateFixedAbsoluteDomainErrorIdentity {
        self.owner.as_fixed_absolute_domain()
    }

    /// Construction accounting retained once by this attempt's exact owner.
    #[must_use]
    pub fn owner_build_accounting(&self) -> &AggregateFixedAbsoluteDomainBuildAccounting {
        &self.owner.fixed_absolute_domain_seal().build
    }

    /// The one complete terminal receipt paired with this construction owner.
    #[must_use]
    pub const fn receipt(&self) -> &AggregateFixedAbsoluteDomainAttemptReceipt {
        &self.receipt
    }
}

/// Exact attempted execution identity. Incumbent failures preserve their
/// pre-U1 boxed cache identity. Fixed failures retain one opaque owner/receipt
/// pair, with no duplicate P/A payload.
#[derive(Clone, Debug, Eq, PartialEq)]
#[allow(
    clippy::large_enum_variant,
    reason = "fixed failures retain one allocation-free lossless owner/receipt identity; boxing would change that contract"
)]
pub enum AggregateExecutionAttemptIdentity {
    Incumbent(Box<AggregateCacheIdentity>),
    /// Construction-owned direct reducer and its one terminal receipt.
    Direct(Box<AggregateDirectAttemptIdentity>),
    /// Continuation construction identity plus the one complete selected-route
    /// execution receipt.
    Continuation {
        cache: Box<AggregateCacheIdentity>,
        receipt: OperationAttemptReceipt,
    },
    FixedAbsoluteDomain(AggregateFixedAbsoluteDomainAttemptIdentity),
}

impl AggregateExecutionAttemptIdentity {
    fn incumbent(identity: Box<AggregateCacheIdentity>) -> Self {
        Self::Incumbent(identity)
    }

    fn fixed_absolute_domain(
        owner: AggregateExecutionIdentity,
        receipt: AggregateFixedAbsoluteDomainAttemptReceipt,
    ) -> Self {
        Self::FixedAbsoluteDomain(AggregateFixedAbsoluteDomainAttemptIdentity::new(
            owner, receipt,
        ))
    }

    fn direct(cache: AggregateCacheIdentity, receipt: AggregateDirectAttemptReceipt) -> Self {
        Self::Direct(Box::new(AggregateDirectAttemptIdentity { cache, receipt }))
    }

    fn continuation(cache: Box<AggregateCacheIdentity>, receipt: OperationAttemptReceipt) -> Self {
        Self::Continuation { cache, receipt }
    }

    #[must_use]
    pub fn as_cache_identity(&self) -> Option<&AggregateCacheIdentity> {
        match self {
            Self::Incumbent(identity) => Some(identity),
            Self::Direct(attempt) => Some(attempt.cache_identity()),
            Self::Continuation { cache, .. } => Some(cache),
            Self::FixedAbsoluteDomain(_) => None,
        }
    }

    /// The opaque fixed-domain owner/receipt pair for this attempt.
    #[must_use]
    pub const fn as_fixed_absolute_domain_attempt(
        &self,
    ) -> Option<&AggregateFixedAbsoluteDomainAttemptIdentity> {
        match self {
            Self::Incumbent(_) | Self::Direct(_) | Self::Continuation { .. } => None,
            Self::FixedAbsoluteDomain(attempt) => Some(attempt),
        }
    }

    #[must_use]
    pub fn as_fixed_absolute_domain(&self) -> Option<&AggregateFixedAbsoluteDomainErrorIdentity> {
        match self {
            Self::Incumbent(_) | Self::Direct(_) | Self::Continuation { .. } => None,
            Self::FixedAbsoluteDomain(attempt) => Some(attempt.owner_identity()),
        }
    }

    /// The one complete fixed-domain attempt receipt retained by this failure.
    #[must_use]
    pub const fn fixed_absolute_domain_receipt(
        &self,
    ) -> Option<&AggregateFixedAbsoluteDomainAttemptReceipt> {
        match self {
            Self::Incumbent(_) | Self::Direct(_) | Self::Continuation { .. } => None,
            Self::FixedAbsoluteDomain(attempt) => Some(attempt.receipt()),
        }
    }

    /// Construction-owned terminal receipt for a direct reducer.
    #[must_use]
    pub const fn direct_receipt(&self) -> Option<&AggregateDirectAttemptReceipt> {
        match self {
            Self::Direct(attempt) => Some(attempt.receipt()),
            Self::Incumbent(_) | Self::Continuation { .. } | Self::FixedAbsoluteDomain(_) => None,
        }
    }

    /// Complete selected-route continuation receipt retained by this attempt.
    #[must_use]
    pub const fn continuation_receipt(&self) -> Option<&OperationAttemptReceipt> {
        match self {
            Self::Continuation { receipt, .. } => Some(receipt),
            Self::Incumbent(_) | Self::Direct(_) | Self::FixedAbsoluteDomain(_) => None,
        }
    }

    fn closes_direct_source_kind(&self, source: &AggregateExecutionSource) -> bool {
        match self {
            Self::Direct(attempt) => attempt.receipt.closes(&attempt.cache, source),
            Self::Incumbent(_) | Self::Continuation { .. } | Self::FixedAbsoluteDomain(_) => false,
        }
    }

    fn closes_fixed_source_kind(&self, source: &AggregateExecutionSource) -> bool {
        match (self, source) {
            (Self::FixedAbsoluteDomain(attempt), AggregateExecutionSource::FixedAbsoluteDomain) => {
                attempt.owner.has_closed_fixed_construction()
                    && attempt.receipt().guard_error().is_some()
            }
            (
                Self::FixedAbsoluteDomain(attempt),
                AggregateExecutionSource::FixedAbsoluteDomainResidual,
            ) => {
                attempt.owner.has_closed_fixed_construction()
                    && attempt.receipt().residual_error().is_some_and(
                        |(continuation, composite)| {
                            continuation.closes()
                                && continuation
                                    .receipt
                                    .identity
                                    .authenticates_limits(attempt.receipt().continuation_limits())
                                && composite.contains_actual_with(&continuation.receipt)
                        },
                    )
            }
            (
                Self::Continuation { cache, receipt },
                AggregateExecutionSource::Continuation(source),
            ) => {
                let operation_matches = matches!(
                    (cache.operation, receipt.identity.operation),
                    (AggregateOperation::Spans, OperationAttemptKind::Spans)
                        | (AggregateOperation::Count, OperationAttemptKind::Count)
                        | (AggregateOperation::SpanSum, OperationAttemptKind::SpanSum)
                );
                let plan_matches = matches!(
                    cache.plan_identity,
                    AggregatePlanIdentity::Continuation(identity)
                        if identity.program == receipt.identity.regex_plan_id
                );
                operation_matches
                    && plan_matches
                    && cache.has_closed_construction_attempt()
                    && receipt.authenticates_source(source)
                    && cache.continuation_strategy == Some(receipt.identity.strategy)
                    && receipt
                        .identity
                        .authenticates_limits(cache.execution_limits.continuation)
                    && receipt.prospective.is_some_and(|upper| {
                        upper.contains(receipt.actual)
                            && receipt.actual_allocations <= upper.allocations
                            && receipt.actual_allocations <= receipt.allocation_limit
                    })
            }
            _ => false,
        }
    }
}

/// Why a forced exact-literal construction was semantically ineligible.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AggregateLiteralIneligibility {
    /// Complete span materialization is not implemented by this reducer.
    SpanOperation,
    /// After peeling only direct root captures, canonical HIR was not one
    /// `Literal` or `Empty` node.
    CanonicalRootNotLiteralOrEmpty,
    /// Unicode-enabled direct execution admits only one nonempty canonical
    /// literal; captures and every other HIR root remain outside scope.
    UnicodeCanonicalRootNotNonemptyLiteral,
    /// Unicode-enabled empty matching remains outside this narrowly promoted
    /// admission even though the pinned bytes oracle advances by bytes.
    UnicodeEmptyOutsideAdmission,
    /// Unicode-enabled exact-literal admission does not certify case folding.
    UnicodeCaseInsensitiveOutsideAdmission,
    /// A local Unicode-disable group produced a raw-byte literal outside the
    /// nonempty valid-UTF-8 literal proof.
    UnicodeLiteralNotUtf8,
}

/// Aggregate construction failure retaining the requested operation/policy.
#[derive(Debug)]
#[non_exhaustive]
#[allow(
    clippy::large_enum_variant,
    reason = "typed build refusals retain complete lossless accounting without post-failure allocation"
)]
pub enum AggregateBuildError {
    /// Syntax/profile/admission failure.
    Syntax {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: fre_syntax::ParseError,
    },
    /// Allocation-free exact-literal inspection crossed its explicit work cap.
    LiteralPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Allocation-free root scalar-class inspection crossed its structural
    /// work cap.
    UnicodeScalarPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Direct word-run inspection crossed its independent structural cap.
    WordRunPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Line-assertion literal inspection crossed its independent structural
    /// work cap.
    LiteralAssertionsPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Blocking-delimiter inspection crossed its independent structural cap.
    BlockingDelimiterPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// ASCII token-phrase inspection crossed its independent structural cap.
    TokenPhrasePlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Fixed class-sandwich inspection crossed its structural work cap.
    FixedClassSandwichPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Direct bounded-affix inspection crossed its independent structural
    /// work cap.
    BoundedAffixPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Ordered scalar-grammar inspection crossed its structural work cap.
    GraphemeScalarDfaPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Bounded compound byte-class inspection crossed its independent
    /// structural work cap.
    BoundedClassSequencePlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Bounded separated-field inspection crossed its independent structural
    /// work cap.
    BoundedSeparatedFieldsPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Prefix/class alternation inspection crossed its structural work cap.
    PrefixClassAlternationPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Literal/class-run/literal inspection crossed its structural work cap.
    LiteralClassRunLiteralPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Swapped bounded literal-pair inspection crossed its independent
    /// structural work cap.
    BoundedLiteralPairPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Bounded-context inspection crossed its structural work cap.
    BoundedContextPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
    },
    /// Fixed absolute-domain canonical-HIR inspection crossed its independent
    /// work cap.
    FixedAbsoluteDomainPlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: usize,
        limit: usize,
        consumed: usize,
    },
    /// Finite-language extraction crossed its explicit work cap.
    FinitePlannerWorkLimit {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        needed: u64,
        limit: u64,
    },
    /// A checked finite-language planner allocation failed.
    FinitePlannerAllocationFailed {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        structure: &'static str,
        additional: usize,
    },
    /// A forced exact-literal request was not semantically eligible.
    ExactLiteralIneligible {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        reason: AggregateLiteralIneligibility,
    },
    /// Exact-literal kernel construction failed after plan selection.
    ExactLiteralBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: LiteralAggregateBuildError,
    },
    /// Compact Unicode scalar-class construction failed after selection.
    UnicodeScalarBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: UnicodeScalarAggregateBuildError,
    },
    /// Direct word-run construction failed after selection.
    WordRunBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: unicode_word_run::AggregateBuildError,
    },
    /// Direct line-assertion literal construction failed after selection.
    LiteralAssertionsBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: LiteralAssertionsBuildError,
    },
    /// Direct blocking-delimiter construction failed after selection.
    BlockingDelimiterBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: BlockingDelimiterBuildError,
    },
    /// Direct ASCII token-phrase construction failed after selection.
    TokenPhraseBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: TokenPhraseBuildError,
    },
    /// Fixed class-sandwich construction failed after selection.
    FixedClassSandwichBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: FixedClassSandwichBuildError,
    },
    /// Ordered scalar-property classifier construction failed after selection.
    GraphemeScalarDfaBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: GraphemeScalarDfaBuildError,
    },
    /// Bounded compound byte-class construction failed after selection.
    BoundedClassSequenceBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: BoundedClassSequenceBuildError,
    },
    /// Bounded separated-field construction failed after selection.
    BoundedSeparatedFieldsBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: BoundedSeparatedFieldsBuildError,
    },
    /// Prefix/class alternation construction failed after selection.
    PrefixClassAlternationBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: PrefixClassAlternationBuildError,
    },
    /// Literal/class-run/literal construction failed after selection.
    LiteralClassRunLiteralBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: LiteralClassRunLiteralBuildError,
    },
    /// Unicode reverse-inner construction failed after selection.
    ReverseInnerBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: ReverseInnerBuildError,
    },
    /// Swapped bounded literal-pair construction failed after selection.
    BoundedLiteralPairBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: BoundedLiteralPairBuildError,
    },
    /// Bounded-context construction failed after selection.
    BoundedContextBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: BoundedContextBuildError,
    },
    /// Fixed absolute-domain guard construction failed after route selection.
    FixedAbsoluteDomainBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        /// Classifier, structural inspection, and scalar census work already
        /// consumed before the selected guard construction failed.
        planner_work: usize,
        source: FixedAbsoluteDomainBuildError,
    },
    /// Scalar guard construction failed after the outer composite P was
    /// published but before either artifact became publishable.
    FixedAbsoluteDomainResidualGuardBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        /// Classifier, structural inspection, and allocation-census work
        /// already consumed before guard construction failed.
        planner_work: usize,
        source: FixedAbsoluteDomainBuildError,
        composite: AggregateFixedAbsoluteDomainResidualBuildAttemptReceipt,
    },
    /// The complete scalar guard-plus-residual envelope exceeded its U1-only
    /// cap before either artifact was constructed.
    FixedAbsoluteDomainResidualPreflight {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        /// Classifier, structural inspection, and allocation-census work
        /// already consumed before this outer preflight refusal.
        planner_work: usize,
        resource: AggregateFixedAbsoluteDomainResidualBuildResource,
        needed: u64,
        limit: u64,
        receipt: AggregateFixedAbsoluteDomainResidualBuildAttemptReceipt,
    },
    /// The scalar guard was selected, but its required eager continuation
    /// residual failed before composite publication.
    FixedAbsoluteDomainResidualCompile {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        /// Classifier, structural inspection, and allocation-census work
        /// already consumed before eager residual compilation began.
        planner_work: usize,
        strategy: AggregateStrategy,
        /// Completed, still-owner-local guard construction receipt.
        guard: FixedAbsoluteDomainBuildAccounting,
        /// Partial residual compiler ledger. Its receipt is unpublished and
        /// binds the exact continuation limits/profile used by this attempt.
        source: AggregateCompileAttemptError,
        /// Cumulative outer P/A; `published` remains false on this terminal
        /// construction failure.
        composite: AggregateFixedAbsoluteDomainResidualBuildAttemptReceipt,
    },
    /// Bounded packed finite-literal construction failed after selection.
    /// Only caller-selected resource ceilings may fall through to the dense
    /// finite representation.
    PackedFiniteLiteralBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: PackedOrderedLiteralAggregateBuildError,
    },
    /// Reversed finite-language DFA construction failed after selection.
    FiniteLiteralBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: OrderedLiteralAggregateBuildError,
    },
    /// Sparse reversed finite-language automaton construction failed after
    /// selection. Caller-selected resource refusals remain optional in
    /// `Auto`; allocator, arithmetic, representation and proof failures do
    /// not get disguised by a continuation retry.
    SparseFiniteLiteralBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: SparseOrderedLiteralAggregateBuildError,
    },
    /// Guarded dictionary construction failed after its complete envelope was
    /// admitted and before publication.
    GuardedAsciiWordBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: guarded_ascii_word::BuildError,
    },
    /// Guarded Unicode-word maximal-run construction failed after semantic
    /// selection.
    GuardedUnicodeWordBuild {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: guarded_unicode_word::BuildError,
    },
    /// Fixed byte-predicate Shift-And construction failed after
    /// semantic selection.
    FixedPredicateWord64Build {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        source: FixedPredicateWord64BuildError,
    },
    /// Bounded continuation compiler refusal.
    ContinuationCompile {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        strategy: AggregateStrategy,
        source: AggregateEngineError,
    },
    /// Parser summary and selected bounded traversal accounting disagreed.
    InternalInvariant {
        operation: AggregateOperation,
        selection: AggregatePlanSelection,
        detail: &'static str,
    },
}

impl AggregateBuildError {
    #[allow(
        clippy::too_many_lines,
        reason = "one exhaustive projection keeps every public error variant bound to its request coordinates"
    )]
    fn construction_request_coordinates(&self) -> (AggregateOperation, AggregatePlanSelection) {
        match self {
            Self::Syntax {
                operation,
                selection,
                ..
            }
            | Self::LiteralPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::UnicodeScalarPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::WordRunPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::LiteralAssertionsPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::BlockingDelimiterPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::TokenPhrasePlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::FixedClassSandwichPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::BoundedAffixPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::GraphemeScalarDfaPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::BoundedClassSequencePlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::BoundedSeparatedFieldsPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::PrefixClassAlternationPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::LiteralClassRunLiteralPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::BoundedLiteralPairPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::BoundedContextPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::FixedAbsoluteDomainPlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::FinitePlannerWorkLimit {
                operation,
                selection,
                ..
            }
            | Self::FinitePlannerAllocationFailed {
                operation,
                selection,
                ..
            }
            | Self::ExactLiteralIneligible {
                operation,
                selection,
                ..
            }
            | Self::ExactLiteralBuild {
                operation,
                selection,
                ..
            }
            | Self::UnicodeScalarBuild {
                operation,
                selection,
                ..
            }
            | Self::WordRunBuild {
                operation,
                selection,
                ..
            }
            | Self::LiteralAssertionsBuild {
                operation,
                selection,
                ..
            }
            | Self::BlockingDelimiterBuild {
                operation,
                selection,
                ..
            }
            | Self::TokenPhraseBuild {
                operation,
                selection,
                ..
            }
            | Self::FixedClassSandwichBuild {
                operation,
                selection,
                ..
            }
            | Self::GraphemeScalarDfaBuild {
                operation,
                selection,
                ..
            }
            | Self::BoundedClassSequenceBuild {
                operation,
                selection,
                ..
            }
            | Self::BoundedSeparatedFieldsBuild {
                operation,
                selection,
                ..
            }
            | Self::PrefixClassAlternationBuild {
                operation,
                selection,
                ..
            }
            | Self::LiteralClassRunLiteralBuild {
                operation,
                selection,
                ..
            }
            | Self::ReverseInnerBuild {
                operation,
                selection,
                ..
            }
            | Self::BoundedLiteralPairBuild {
                operation,
                selection,
                ..
            }
            | Self::BoundedContextBuild {
                operation,
                selection,
                ..
            }
            | Self::FixedAbsoluteDomainBuild {
                operation,
                selection,
                ..
            }
            | Self::FixedAbsoluteDomainResidualGuardBuild {
                operation,
                selection,
                ..
            }
            | Self::FixedAbsoluteDomainResidualPreflight {
                operation,
                selection,
                ..
            }
            | Self::FixedAbsoluteDomainResidualCompile {
                operation,
                selection,
                ..
            }
            | Self::FiniteLiteralBuild {
                operation,
                selection,
                ..
            }
            | Self::PackedFiniteLiteralBuild {
                operation,
                selection,
                ..
            }
            | Self::SparseFiniteLiteralBuild {
                operation,
                selection,
                ..
            }
            | Self::GuardedAsciiWordBuild {
                operation,
                selection,
                ..
            }
            | Self::GuardedUnicodeWordBuild {
                operation,
                selection,
                ..
            }
            | Self::FixedPredicateWord64Build {
                operation,
                selection,
                ..
            }
            | Self::ContinuationCompile {
                operation,
                selection,
                ..
            }
            | Self::InternalInvariant {
                operation,
                selection,
                ..
            } => (*operation, *selection),
        }
    }

    fn closes_construction_terminal_stage(&self, stage: AggregateConstructionStage) -> bool {
        match self {
            Self::Syntax { .. } => stage == AggregateConstructionStage::SyntaxParseAdmission,
            Self::LiteralPlannerWorkLimit { .. } | Self::ExactLiteralBuild { .. } => {
                stage == AggregateConstructionStage::ExactLiteral
            }
            Self::ExactLiteralIneligible { .. } => matches!(
                stage,
                AggregateConstructionStage::PreSyntaxForceExactLiteralSpans
                    | AggregateConstructionStage::ExactLiteral
            ),
            Self::UnicodeScalarPlannerWorkLimit { .. } | Self::UnicodeScalarBuild { .. } => {
                stage == AggregateConstructionStage::UnicodeScalar
            }
            Self::WordRunPlannerWorkLimit { .. } | Self::WordRunBuild { .. } => {
                stage == AggregateConstructionStage::WordRun
            }
            Self::LiteralAssertionsPlannerWorkLimit { .. }
            | Self::LiteralAssertionsBuild { .. } => {
                stage == AggregateConstructionStage::LiteralAssertions
            }
            Self::BlockingDelimiterPlannerWorkLimit { .. }
            | Self::BlockingDelimiterBuild { .. } => {
                stage == AggregateConstructionStage::BlockingDelimiter
            }
            Self::TokenPhrasePlannerWorkLimit { .. } | Self::TokenPhraseBuild { .. } => {
                stage == AggregateConstructionStage::TokenPhrase
            }
            Self::FixedClassSandwichPlannerWorkLimit { .. }
            | Self::FixedClassSandwichBuild { .. } => {
                stage == AggregateConstructionStage::FixedClassSandwich
            }
            Self::BoundedAffixPlannerWorkLimit { .. } => {
                stage == AggregateConstructionStage::BoundedAffix
            }
            Self::GraphemeScalarDfaPlannerWorkLimit { .. }
            | Self::GraphemeScalarDfaBuild { .. } => {
                stage == AggregateConstructionStage::GraphemeScalarDfa
            }
            Self::BoundedClassSequencePlannerWorkLimit { .. }
            | Self::BoundedClassSequenceBuild { .. } => {
                stage == AggregateConstructionStage::BoundedClassSequence
            }
            Self::BoundedSeparatedFieldsPlannerWorkLimit { .. }
            | Self::BoundedSeparatedFieldsBuild { .. } => {
                stage == AggregateConstructionStage::BoundedSeparatedFields
            }
            Self::PrefixClassAlternationPlannerWorkLimit { .. }
            | Self::PrefixClassAlternationBuild { .. } => {
                stage == AggregateConstructionStage::PrefixClassAlternation
            }
            Self::LiteralClassRunLiteralPlannerWorkLimit { .. }
            | Self::LiteralClassRunLiteralBuild { .. }
            | Self::ReverseInnerBuild { .. } => {
                stage == AggregateConstructionStage::LiteralClassRunLiteral
            }
            Self::BoundedLiteralPairPlannerWorkLimit { .. }
            | Self::BoundedLiteralPairBuild { .. } => {
                stage == AggregateConstructionStage::BoundedLiteralPair
            }
            Self::BoundedContextPlannerWorkLimit { .. } => {
                stage == AggregateConstructionStage::BoundedContext
            }
            Self::BoundedContextBuild { .. } => matches!(
                stage,
                AggregateConstructionStage::BoundedAffix
                    | AggregateConstructionStage::BoundedContext
            ),
            Self::FixedAbsoluteDomainPlannerWorkLimit { .. }
            | Self::FixedAbsoluteDomainBuild { .. }
            | Self::FixedAbsoluteDomainResidualGuardBuild { .. }
            | Self::FixedAbsoluteDomainResidualPreflight { .. }
            | Self::FixedAbsoluteDomainResidualCompile { .. } => {
                stage == AggregateConstructionStage::FixedAbsolute
            }
            Self::FinitePlannerWorkLimit { .. } | Self::FinitePlannerAllocationFailed { .. } => {
                matches!(
                    stage,
                    AggregateConstructionStage::SparseFiniteRoot
                        | AggregateConstructionStage::GeneralFiniteExtraction
                        | AggregateConstructionStage::PackedFinite
                        | AggregateConstructionStage::DenseFinite
                        | AggregateConstructionStage::FixedPredicateWord64
                )
            }
            Self::PackedFiniteLiteralBuild { .. } => {
                stage == AggregateConstructionStage::PackedFinite
            }
            Self::FiniteLiteralBuild { .. } => stage == AggregateConstructionStage::DenseFinite,
            Self::SparseFiniteLiteralBuild { .. } => {
                stage == AggregateConstructionStage::SparseFiniteRoot
            }
            Self::GuardedAsciiWordBuild { .. } | Self::GuardedUnicodeWordBuild { .. } => {
                stage == AggregateConstructionStage::GeneralFiniteExtraction
            }
            Self::FixedPredicateWord64Build { .. } => {
                stage == AggregateConstructionStage::FixedPredicateWord64
            }
            Self::ContinuationCompile { .. } => stage == AggregateConstructionStage::Continuation,
            Self::InternalInvariant { .. } => true,
        }
    }
}

/// Terminal whole-construction error with the same closed transaction receipt
/// exposed by successful build reports.
#[derive(Debug)]
#[allow(
    clippy::large_enum_variant,
    reason = "the exact request must remain allocation-free on error; boxing after failure would add an unbudgeted effect"
)]
enum AggregateConstructionSourceOwner {
    Request(fre_syntax::ParseRequest),
    CacheKey(Arc<CacheKey>),
}

#[derive(Debug)]
pub struct AggregateConstructionAttemptError {
    source: AggregateBuildError,
    receipt: AggregateConstructionReceipt,
    source_owner: AggregateConstructionSourceOwner,
    syntax_attempt: Option<fre_syntax::ParseAttemptReceipt>,
    sealed_stage: crate::AggregateConstructionStage,
}

impl AggregateConstructionAttemptError {
    fn new(
        source: AggregateBuildError,
        receipt: AggregateConstructionReceipt,
        source_owner: AggregateConstructionSourceOwner,
        syntax_attempt: Option<fre_syntax::ParseAttemptReceipt>,
        sealed_stage: crate::AggregateConstructionStage,
    ) -> Self {
        Self {
            source,
            receipt,
            source_owner,
            syntax_attempt,
            sealed_stage,
        }
    }

    /// Legacy typed aggregate construction source.
    #[must_use]
    pub const fn source(&self) -> &AggregateBuildError {
        &self.source
    }

    /// Closed request/P/A/stage terminal receipt.
    #[must_use]
    pub const fn receipt(&self) -> &AggregateConstructionReceipt {
        &self.receipt
    }

    /// Nested syntax receipt, absent only for a terminal before parsing began.
    #[must_use]
    pub const fn syntax_attempt_receipt(&self) -> Option<&fre_syntax::ParseAttemptReceipt> {
        self.syntax_attempt.as_ref()
    }

    /// Authenticate the private source/terminal pairing and closed failure
    /// transaction.
    #[must_use]
    pub fn closes(&self) -> bool {
        let request = self.receipt.identity.request_owner.request();
        let syntax_identity = &request.syntax_request;
        let (source_operation, source_selection) = self.source.construction_request_coordinates();
        let source_owner_closes =
            self.receipt.prospective.is_none() || syntax_identity.has_stable_source_owner();
        let source_closes = match &self.source_owner {
            AggregateConstructionSourceOwner::Request(request) => {
                syntax_identity.authenticates_request(request)
            }
            AggregateConstructionSourceOwner::CacheKey(key) => {
                syntax_identity.authenticates_key(key)
            }
        };
        let syntax_closes = self.syntax_attempt.as_ref().map_or_else(
            || {
                self.sealed_stage
                    == crate::AggregateConstructionStage::PreSyntaxForceExactLiteralSpans
            },
            |syntax| {
                syntax.authenticates_canonical()
                    && syntax.identity == *syntax_identity
                    && match &self.source_owner {
                        AggregateConstructionSourceOwner::Request(request) => {
                            syntax.authenticates_request(request)
                                && syntax.terminal == fre_syntax::ParseAttemptTerminal::Failure
                        }
                        AggregateConstructionSourceOwner::CacheKey(key) => {
                            syntax.identity.authenticates_key(key)
                                && syntax.terminal == fre_syntax::ParseAttemptTerminal::Success
                        }
                    }
            },
        );
        self.receipt.closes(&self.receipt.identity, None)
            && self.receipt.terminal == crate::AggregateConstructionTerminal::Failure
            && self.receipt.identity.explain_schema_version == AGGREGATE_EXPLAIN_SCHEMA_VERSION
            && source_owner_closes
            && source_closes
            && syntax_closes
            && request.operation == source_operation
            && request.selection == source_selection
            && self
                .source
                .closes_construction_terminal_stage(self.sealed_stage)
            && self
                .receipt
                .ledger
                .get(self.receipt.ledger.len().saturating_sub(1))
                .is_some_and(|entry| {
                    entry.stage == self.sealed_stage
                        && entry.disposition
                            == crate::AggregateConstructionStageDisposition::HardTerminal
                })
    }

    /// Consume the wrapper without allocating or changing the legacy source.
    #[must_use]
    pub fn into_source(self) -> AggregateBuildError {
        self.source
    }

    /// Consume both exact terminal components.
    #[must_use]
    pub fn into_parts(self) -> (AggregateBuildError, AggregateConstructionReceipt) {
        (self.source, self.receipt)
    }
}

impl fmt::Display for AggregateConstructionAttemptError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.source, formatter)
    }
}

impl std::error::Error for AggregateConstructionAttemptError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.source)
    }
}

