    // Keep the entry dispatcher as a small route selector. In particular,
    // direct Unicode count plans should not inherit stack probes or code
    // placement from receipt-heavy fallback routes.
    #[inline(never)]
    fn execute_count_value(
        &self,
        haystack: &[u8],
        limits: &AggregateRunLimits,
    ) -> Result<u64, AggregateExecutionError> {
        if let Some(value) = self.impossible_match_domain_value(haystack.len(), limits) {
            return Ok(value);
        }
        match &self.engine {
            AggregateEngine::ExactLiteral(engine) => {
                self.execute_exact_literal_count_value(engine, haystack, limits)
            }
            AggregateEngine::DispatchedExactLiteral(engine) => {
                self.execute_dispatched_exact_literal_count_value(engine, haystack, limits)
            }
            AggregateEngine::FiniteCount(engine) => {
                self.execute_dense_finite_count_value(engine, haystack, limits)
            }
            AggregateEngine::FixedAbsoluteDomain(engine) => {
                self.execute_fixed_absolute_count_value(engine, haystack, limits)
            }
            AggregateEngine::UnicodeScalar(engine) => {
                self.execute_unicode_scalar_count_value(engine, haystack, limits)
            }
            AggregateEngine::DispatchedUnicodeScalar(engine) => {
                self.execute_dispatched_unicode_scalar_count_value(engine, haystack, limits)
            }
            AggregateEngine::Continuation(engine) => {
                self.execute_continuation_count_value(engine, haystack, limits)
            }
            AggregateEngine::FixedPredicateWord64(engine) => {
                self.execute_fixed_predicate_count_value(engine, haystack, limits)
            }
            AggregateEngine::BoundedSeparatedFields(engine) => {
                self.execute_bounded_separated_fields_count_value(engine, haystack, limits)
            }
            AggregateEngine::AsciiWordRun(engine) => {
                self.execute_ascii_word_run_count_value(engine, haystack, limits)
            }
            AggregateEngine::WordRun(engine) if engine.is_fixed_class_chunks() => {
                self.execute_fixed_chunk_word_run_count_value(engine, haystack, limits)
            }
            _ => self.execute_count_value_fallback(haystack, limits),
        }
    }

    fn execute_count_value_with_workspace(
        &self,
        haystack: &[u8],
        limits: &AggregateRunLimits,
        dense_finite: &mut OrderedLiteralCountWorkspace,
        continuation: &mut ContinuationSweepWorkspace,
    ) -> Result<u64, AggregateExecutionError> {
        match &self.engine {
            AggregateEngine::FiniteCount(engine) => {
                if let Some(value) = self.impossible_match_domain_value(haystack.len(), limits) {
                    return Ok(value);
                }
                self.execute_dense_finite_count_value_with_workspace(
                    engine,
                    haystack,
                    limits,
                    dense_finite,
                )
            }
            AggregateEngine::Continuation(engine) => {
                if let Some(value) = self.impossible_match_domain_value(haystack.len(), limits) {
                    return Ok(value);
                }
                match engine.count_value_with_sweep_workspace(
                    haystack,
                    Self::full_range(haystack),
                    self.report.continuation_strategy.ok_or_else(|| {
                        self.execution_error(
                            limits,
                            AggregateExecutionSource::InternalInvariant(
                                "continuation count plan lacks storage strategy",
                            ),
                        )
                    })?,
                    limits.continuation,
                    continuation,
                ) {
                    Ok(Some(value)) => u64::try_from(value).map_err(|_| {
                        self.execution_error(
                            limits,
                            AggregateExecutionSource::InternalInvariant(
                                "continuation sweep count does not fit u64",
                            ),
                        )
                    }),
                    Ok(None) => self.execute_continuation_count_value(engine, haystack, limits),
                    Err(source) => Err(self
                        .execution_error(limits, AggregateExecutionSource::Continuation(source))),
                }
            }
            _ => self.execute_count_value(haystack, limits),
        }
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the exhaustive scalar dispatch avoids constructing the large audited result enum"
    )]
    #[inline(never)]
    fn execute_count_value_fallback(
        &self,
        haystack: &[u8],
        limits: &AggregateRunLimits,
    ) -> Result<u64, AggregateExecutionError> {
        match &self.engine {
            AggregateEngine::ExactLiteral(engine) => {
                self.execute_exact_literal_count_value(engine, haystack, limits)
            }
            AggregateEngine::DispatchedExactLiteral(engine) => {
                self.execute_dispatched_exact_literal_count_value(engine, haystack, limits)
            }
            AggregateEngine::UnicodeScalar(engine) => {
                self.execute_unicode_scalar_count_value(engine, haystack, limits)
            }
            AggregateEngine::DispatchedUnicodeScalar(engine) => {
                self.execute_dispatched_unicode_scalar_count_value(engine, haystack, limits)
            }
            AggregateEngine::WordRun(engine) => engine
                .aggregate_count(haystack, limits.word_run)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::WordRun(source),
                    )
                }),
            AggregateEngine::AsciiWordRun(engine) => {
                self.execute_ascii_word_run_count_value(engine, haystack, limits)
            }
            AggregateEngine::LiteralAssertions(engine) => engine
                .count(haystack, limits.literal_assertions)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::LiteralAssertions(source),
                    )
                }),
            AggregateEngine::BlockingDelimiter(engine) => engine
                .count(haystack, limits.blocking_delimiter)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::BlockingDelimiter(source),
                    )
                }),
            AggregateEngine::TokenPhrase(engine) => engine
                .count(haystack, limits.token_phrase)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::TokenPhrase(source),
                    )
                }),
            AggregateEngine::FixedClassSandwich(engine) => engine
                .count(haystack, limits.fixed_class_sandwich)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::FixedClassSandwich(source),
                    )
                }),
            AggregateEngine::GraphemeScalarDfa(engine) => engine
                .count(haystack, limits.grapheme_scalar_dfa)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::GraphemeScalarDfa(source),
                    )
                }),
            AggregateEngine::BoundedClassSequence(engine) => engine
                .count(haystack, limits.bounded_class_sequence)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::BoundedClassSequence(source),
                    )
                }),
            AggregateEngine::BoundedSeparatedFields(engine) => engine
                .count(haystack, limits.bounded_separated_fields)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::BoundedSeparatedFields(source),
                    )
                }),
            AggregateEngine::PrefixClassAlternation(engine) => engine
                .count(haystack, limits.prefix_class_alternation)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::PrefixClassAlternation(source),
                    )
                }),
            AggregateEngine::LiteralClassRunLiteral(engine) => engine
                .count(haystack, limits.literal_class_run_literal)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::LiteralClassRunLiteral(source),
                    )
                }),
            AggregateEngine::ReverseInner(engine) => engine
                .count(haystack, limits.reverse_inner)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::ReverseInner(source),
                    )
                }),
            AggregateEngine::BoundedLiteralPair(engine) => engine
                .count(haystack, limits.bounded_literal_pair)
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::BoundedLiteralPair(source),
                    )
                }),
            AggregateEngine::BoundedContext(engine) => {
                if let Some(value) = engine.count_value_success(haystack, limits.bounded_context) {
                    return Ok(value);
                }
                engine
                    .count(haystack, limits.bounded_context)
                    .map(|result| result.count)
                    .map_err(|source| {
                        self.direct_execution_error(
                            haystack.len(),
                            limits,
                            AggregateExecutionSource::BoundedContext(source),
                        )
                    })
            }
            AggregateEngine::FixedAbsoluteDomain(engine) => {
                self.execute_fixed_absolute_count_value(engine, haystack, limits)
            }
            AggregateEngine::PackedFiniteCount(engine) => engine
                .count(haystack, packed_finite_reduce_limits(limits.finite_literal))
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::PackedFiniteLiteral(source),
                    )
                }),
            AggregateEngine::PackedBoundedPrefixCount(engine) => engine
                .count(haystack, packed_finite_reduce_limits(limits.finite_literal))
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::PackedFiniteLiteral(source),
                    )
                }),
            AggregateEngine::PackedFiniteSpanSum(_) => Err(self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant(
                    "count operation retained a packed finite span-sum plan",
                ),
            )),
            AggregateEngine::FiniteCount(engine) => {
                self.execute_dense_finite_count_value(engine, haystack, limits)
            }
            AggregateEngine::FiniteSpanSum(_) => Err(self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant(
                    "count operation retained a finite span-sum plan",
                ),
            )),
            AggregateEngine::SparseFiniteCount(engine) => engine
                .count(haystack, sparse_finite_reduce_limits(limits.finite_literal))
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::SparseFiniteLiteral(source),
                    )
                }),
            AggregateEngine::SparseFiniteSpanSum(_) => Err(self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant(
                    "count operation retained a sparse finite span-sum plan",
                ),
            )),
            AggregateEngine::GuardedAsciiWord(engine) => engine
                .count_auto(
                    haystack,
                    guarded_ascii_word_reduce_limits(limits.finite_literal),
                )
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::GuardedAsciiWord(Box::new(source)),
                    )
                }),
            AggregateEngine::GuardedUnicodeWord(engine) => engine
                .count(
                    haystack,
                    guarded_unicode_word_reduce_limits(limits.finite_literal),
                )
                .map(|result| result.count)
                .map_err(|source| {
                    self.direct_execution_error(
                        haystack.len(),
                        limits,
                        AggregateExecutionSource::GuardedUnicodeWord(Box::new(source)),
                    )
                }),
            AggregateEngine::FixedPredicateWord64(engine) => {
                self.execute_fixed_predicate_count_value(engine, haystack, limits)
            }
            AggregateEngine::Continuation(engine) => {
                self.execute_continuation_count_value(engine, haystack, limits)
            }
        }
    }

    fn execute_continuation_count_value_with_counters(
        &self,
        engine: &CompiledRegex,
        haystack: &[u8],
        limits: &AggregateRunLimits,
    ) -> Result<AggregateValueCounterResult, AggregateExecutionError> {
        let strategy = self.report.continuation_strategy.ok_or_else(|| {
            self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant(
                    "continuation count plan lacks storage strategy",
                ),
            )
        })?;
        let attempt = match engine.count_value_with_counters(
            haystack,
            Self::full_range(haystack),
            strategy,
            limits.continuation,
        ) {
            Ok(attempt) => attempt,
            Err(_) => {
                match self.replay_continuation_count_value(engine, haystack, limits, strategy) {
                    Err(error) => return Err(error),
                    Ok(_) => {
                        return Err(self.execution_error(
                            limits,
                            AggregateExecutionSource::InternalInvariant(
                                "ordinary continuation count failure did not reproduce during authenticated replay",
                            ),
                        ));
                    }
                }
            }
        };
        let value = u64::try_from(attempt.value).map_err(|_| {
            self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant("continuation count does not fit u64"),
            )
        })?;
        Ok(AggregateValueCounterResult {
            value,
            continuation_receipt: Some(attempt.receipt),
        })
    }

    /// Execute the incumbent value-only Count path and retain its optional
    /// hot-path continuation counter receipt. This deliberately does not
    /// introduce a new selector, full attempt receipt, or report-building pass
    /// on success.
    fn execute_count_value_with_counters(
        &self,
        haystack: &[u8],
        limits: &AggregateRunLimits,
    ) -> Result<AggregateValueCounterResult, AggregateExecutionError> {
        let AggregateEngine::Continuation(engine) = &self.engine else {
            return self.execute_count_value(haystack, limits).map(|value| {
                AggregateValueCounterResult {
                    value,
                    continuation_receipt: None,
                }
            });
        };
        if let Some(value) = self.impossible_match_domain_value(haystack.len(), limits) {
            return Ok(AggregateValueCounterResult {
                value,
                continuation_receipt: None,
            });
        }
        self.execute_continuation_count_value_with_counters(engine, haystack, limits)
    }

    // Keep fixed-domain validation and error construction out of the scalar
    // dispatcher, matching the count-value stack-frame boundary above.
    #[inline(never)]
    fn execute_fixed_absolute_span_sum_value(
        &self,
        engine: &AggregateFixedAbsoluteDomainEngine,
        haystack: &[u8],
        limits: &AggregateRunLimits,
    ) -> Result<u64, AggregateExecutionError> {
        if engine.residual.is_some() {
            return Err(self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant(
                    "span-sum fixed-domain route retained a residual",
                ),
            ));
        }
        if let Some(value) = engine
            .guard
            .span_sum_value_success(haystack, limits.fixed_absolute)
        {
            return Ok(value);
        }
        match engine.guard.span_sum(haystack, limits.fixed_absolute) {
            Err(source) => Err(self.fixed_execution_error(
                limits,
                AggregateFixedAbsoluteDomainAttemptFailure::Guard(source),
            )),
            Ok(_) => Err(self.execution_error(
                limits,
                AggregateExecutionSource::InternalInvariant(
                    "compact fixed-domain span-sum refusal did not reproduce during authenticated replay",
                ),
            )),
        }
    }

