enum LiteralInspection<'a> {
    Eligible {
        needle: &'a [u8],
        work: usize,
        captures: usize,
    },
    Ineligible {
        work: usize,
        reason: AggregateLiteralIneligibility,
    },
}

#[derive(Clone, Copy)]
enum LiteralInspectionMode {
    UnicodeOff,
    UnicodeOnNonempty,
}

enum LiteralInspectionError {
    WorkLimit {
        needed: usize,
        limit: usize,
        consumed: usize,
    },
    Overflow {
        consumed: usize,
    },
}

impl LiteralInspectionError {
    const fn consumed_work(&self) -> usize {
        match *self {
            Self::WorkLimit { consumed, .. } | Self::Overflow { consumed } => consumed,
        }
    }
}

